import subprocess
def dbg(q):
    r=subprocess.run(["./executable","-debug",q], capture_output=True, text=True)
    print(q, r.returncode, r.stdout)
    for l in r.stderr.splitlines():
        print(l.split(" ",2)[2] if len(l.split(" ",2))>2 else l)
