    r=subprocess.run(["./executable","-debug","-ir",str(ir),"SELECT * FROM /tmp/n.csv"], capture_output=True, text=True)
    print("ir",ir,r.stdout)
    for l in r.stderr.splitlines(): print(l.split(" ",2)[2])
    print("---")
