# ---------------- logging / fatal handling ----------------
DEBUG = False

def _ts():
    return time.strftime("%Y/%m/%d %H:%M:%S", time.localtime())

def log_line(msg=""):
    # Go log package: prefix each output call once; embedded newlines kept.
    if not isinstance(msg, str):
        msg = str(msg)
    out = f"{_ts()} {msg}"
    if not out.endswith("\n"):
        out += "\n"
    try:
        sys.stderr.write(out)
        sys.stderr.flush()
    except Exception:
        pass

def debug_log(msg=""):
    if DEBUG:
        log_line(msg)

def error_log(msg=""):
    log_line(msg)

class FatalExit(Exception):
    def __init__(self, code=1):
        self.code = code

def fatal(msg=""):
    log_line(msg)
    raise FatalExit(1)

def fatal_import(msg=""):
    fatal(f"import: {msg}")

def fatal_export(msg=""):
    fatal(f"export: {msg}")

# DB cleanup on fatal is handled in main via exception handling around execution.

# ---------------- Go formatting helpers ----------------

def go_quote(s):
    """strconv.Quote for typical strings (Go %q double quoted)"""
    if not isinstance(s, str):
        s = str(s)
    out = ['"']
    for ch in s:
        o = ord(ch)
        if ch == '"':
            out.append('\\"')
        elif ch == '\\':
            out.append('\\\\')
        elif ch == '\n':
            out.append('\\n')
        elif ch == '\r':
            out.append('\\r')
        elif ch == '\t':
            out.append('\\t')
        elif o < 0x20 or o == 0x7f:
            out.append(f'\\x{o:02x}')
        else:
            # Go Quote leaves printable unicode as-is; non-printable as \u
            if unicodedata.category(ch) in ('Cc','Cf','Co','Cs'):
                if o <= 0xffff:
                    out.append(f'\\u{o:04x}')
                else:
                    out.append(f'\\U{o:08x}')
            else:
                out.append(ch)
    out.append('"')
    return ''.join(out)

def go_float_g(v):
    """Approximate Go strconv.FormatFloat(v,'g',-1,64) / fmt.Sprint(float64).
    Go uses shortest repr; exponent form if exp < -4 or exp >= digits threshold
