def go_quote(s):
    """strconv.Quote for typical strings (Go %q double quoted)"""
    if not isinstance(s, str):
        s = str(s)
    out = ['"']
    for ch in s:
        o = ord(ch)
        if ch == '"':
            out.append('\\"')
        elif ch == '\\':
            out.append('\\\\')
        elif ch == '\n':
            out.append('\\n')
        elif ch == '\r':
            out.append('\\r')
        elif ch == '\t':
            out.append('\\t')
        elif o < 0x20 or o == 0x7f:
            out.append(f'\\x{o:02x}')
        else:
            # Go Quote leaves printable unicode as-is; non-printable as \u
            if unicodedata.category(ch) in ('Cc','Cf','Co','Cs'):
                if o <= 0xffff:
                    out.append(f'\\u{o:04x}')
                else:
                    out.append(f'\\U{o:08x}')
            else:
                out.append(ch)
    out.append('"')
    return ''.join(out)

