    if v is None:
        return onull_val if onull_set else ""
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, int):
        return str(v)
    if isinstance(v, float):
        return go_float_g(v)
    if isinstance(v, (bytes, bytearray)):
        b = bytes(v)
        try:
            return b.decode('utf-8')
        except Exception:
            return "\\x" + b.hex()
