def format_time_rfc3339(dt, nano=False):
    # dt is timezone-aware datetime
    # Go time.Time.Format(time.RFC3339) / MarshalJSON uses RFC3339Nano
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=datetime.timezone.utc)
    # Format offset
    offset = dt.utcoffset()
    if offset is None or offset.total_seconds() == 0:
        tzstr = "Z"
        base = dt.strftime("%Y-%m-%dT%H:%M:%S")
    else:
        total = int(offset.total_seconds())
        sign = '+' if total >= 0 else '-'
        total = abs(total)
        tzstr = f"{sign}{total//3600:02d}:{(total%3600)//60:02d}"
        base = dt.strftime("%Y-%m-%dT%H:%M:%S")
    if nano and dt.microsecond:
        frac = f"{dt.microsecond:06d}".rstrip('0')
        base += '.' + frac
    return base + tzstr

def display_width(s):
    width = 0
    for ch in s:
        width += rune_width(ch)
    return width

def rune_width(ch):
    o = ord(ch)
    if o == 0:
        return 0
    if o < 32 or (0x7f <= o < 0xa0):
        return 0
    if unicodedata.combining(ch):
        return 0
    cat = unicodedata.category(ch)
    if cat in ('Mn','Me','Cf'):
        # Zero width joiner etc Cf returns 0 in go-runewidth? Variation selectors are Mn.
        return 0
    eaw = unicodedata.east_asian_width(ch)
    if eaw in ('W','F'):
        return 2
    return 1

def pad_display(s, width, align='left'):
    w = display_width(s)
    if w >= width:
        return s
    pad = width - w
    if align == 'right':
        return ' ' * pad + s
    elif align == 'center':
        left = pad // 2
        # tablewriter centering? We'll later implement specific.
        right = pad - left
        return ' ' * left + s + ' ' * right
    else:
        return s + ' ' * pad

