# ---------------- JSON parser with Go-like errors ----------------
class JsonNumber(str):
    pass

class GoJSONError(Exception):
    pass

class JSONEOF(Exception):
    pass

def _quote_char(c):
    # c is an int byte
    if c == 0x27: # '
        return "'\\''"
    if c == 0x22:
        return "'\"'" if False else "'\\\"'"
    if c == 0x5c:
        return "'\\\\'"
    if c == 0x0a:
        return "'\\n'"
    if c == 0x0d:
        return "'\\r'"
    if c == 0x09:
        return "'\\t'"
    ch = chr(c)
    if c >= 0x20 and c != 0x7f and unicodedata.category(ch) not in ('Cc','Cf','Cs','Co'):
        return "'" + ch + "'"
    return f"'\\u{c:04x}'"

class JSONParser:
    def __init__(self, data: bytes):
