            return self.parse_object()
        if c == 0x5b: # [
            return self.parse_array()
        if c == 0x22: # "
            return self.parse_string()
        if c == 0x74: # t
            return self.parse_literal(b"true", True, "true")
        if c == 0x66:
            return self.parse_literal(b"false", False, "false")
        if c == 0x6e:
            return self.parse_literal(b"null", None, "null")
        if c == 0x2d or (0x30 <= c <= 0x39):
            return self.parse_number()
