                if esc == 0x22: out_parts.append('"')
                elif esc == 0x5c: out_parts.append('\\')
                elif esc == 0x2f: out_parts.append('/')
                elif esc == 0x62: out_parts.append('\b')
                elif esc == 0x66: out_parts.append('\f')
