def go_json_marshal_compact(value):
    """Go json.Marshal for generic values decoded by our parser (and Python objects), with HTML escape,
    sorted map keys, JsonNumber preserved."""
    out = []
    _json_write(value, out, indent=None, level=0, sort_keys=True)
    return ''.join(out)

def _json_escape_string(s):
    # Go encoding/json string encoding with HTML escape on.
    out = ['"']
    for ch in s:
        if ch == '"': out.append('\\"')
        elif ch == '\\': out.append('\\\\')
        elif ch == '\n': out.append('\\n')
        elif ch == '\r': out.append('\\r')
        elif ch == '\t': out.append('\\t')
        elif ch == '<': out.append('\\u003c')
        elif ch == '>': out.append('\\u003e')
        elif ch == '&': out.append('\\u0026')
        elif ch == '\u2028': out.append('\\u2028')
        elif ch == '\u2029': out.append('\\u2029')
        else:
            o = ord(ch)
            if o < 0x20:
                out.append(f'\\u{o:04x}')
            elif 0xD800 <= o <= 0xDFFF:
                out.append('\\ufffd')
            else:
                out.append(ch)
    out.append('"')
    return ''.join(out)

