            raise GoJSONError("unexpected EOF")
        if self.data[self.pos] == 0x5d:
            self.pos += 1
            return arr
        while True:
            self.skip_ws()
            if self.eof():
                raise GoJSONError("unexpected EOF")
            val = self.parse_value()
