    """Go json.Marshal for generic values decoded by our parser (and Python objects), with HTML escape,
    sorted map keys, JsonNumber preserved."""
    out = []
    _json_write(value, out, indent=None, level=0, sort_keys=True)
    return ''.join(out)

def _json_escape_string(s):
    # Go encoding/json string encoding with HTML escape on.
    out = ['"']
    for ch in s:
        if ch == '"': out.append('\\"')
        elif ch == '\\': out.append('\\\\')
        elif ch == '\n': out.append('\\n')
        elif ch == '\r': out.append('\\r')
        elif ch == '\t': out.append('\\t')
        elif ch == '<': out.append('\\u003c')
        elif ch == '>': out.append('\\u003e')
        elif ch == '&': out.append('\\u0026')
        elif ch == '\u2028': out.append('\\u2028')
        elif ch == '\u2029': out.append('\\u2029')
        else:
            o = ord(ch)
            if o < 0x20:
                out.append(f'\\u{o:04x}')
            elif 0xD800 <= o <= 0xDFFF:
                out.append('\\ufffd')
            else:
                out.append(ch)
    out.append('"')
    return ''.join(out)

class RawJSON(str):
    """A string containing raw JSON text to embed (compacted/validated elsewhere)."""
    pass

def _json_write(value, out, indent, level, sort_keys=False):
    # indent = None compact; or string of two spaces for pretty
    if value is None:
        out.append("null"); return
    if isinstance(value, RawJSON):
        # value already contains JSON text; in pretty mode Go MarshalIndent reindents RawMessage.
        if indent is None:
            out.append(compact_raw_json(value))
        else:
            out.append(indent_raw_json(value, indent, level))
        return
    if isinstance(value, bool):
        out.append("true" if value else "false"); return
    if isinstance(value, JsonNumber):
        out.append(str(value)); return
    if isinstance(value, int):
        out.append(str(value)); return
    if isinstance(value, float):
        out.append(go_float_json(value)); return
    if isinstance(value, str):
        out.append(_json_escape_string(value)); return
    if isinstance(value, (bytes,bytearray)):
        out.append(_json_escape_string(go_value_string(bytes(value)))); return
    if isinstance(value, dict):
        items = list(value.items())
        if sort_keys:
            items = sorted(items, key=lambda kv: kv[0])
        if indent is None:
            out.append('{')
            for i,(k,v) in enumerate(items):
                if i: out.append(',')
                out.append(_json_escape_string(str(k)))
                out.append(':')
                _json_write(v,out,indent,level,sort_keys)
            out.append('}')
        else:
            if not items:
                out.append('{}'); return
            out.append('{\n')
            inner_indent = indent*(level+1)
            for i,(k,v) in enumerate(items):
                if i: out.append(',\n')
                out.append(inner_indent)
                out.append(_json_escape_string(str(k)))
                out.append(': ')
                _json_write(v,out,indent,level+1,sort_keys)
            out.append('\n')
            out.append(indent*level)
            out.append('}')
        return
    if isinstance(value, (list,tuple)):
        if indent is None:
            out.append('[')
            for i,v in enumerate(value):
                if i: out.append(',')
                _json_write(v,out,indent,level,sort_keys)
            out.append(']')
        else:
            if not value:
                out.append('[]'); return
            out.append('[\n')
            inner_indent = indent*(level+1)
            for i,v in enumerate(value):
                if i: out.append(',\n')
                out.append(inner_indent)
                _json_write(v,out,indent,level+1,sort_keys)
            out.append('\n')
            out.append(indent*level)
            out.append(']')
        return
    if isinstance(value, datetime.datetime):
        out.append(_json_escape_string(format_time_rfc3339(value, nano=True))); return
    out.append(_json_escape_string(str(value)))

def compact_raw_json(raw):
    """Go json.Compact equivalent (with HTML escaping performed by Marshal for RawMessage? Observed < > & escaped).
    Our RawJSON originally is user string; we compact whitespace outside strings, preserve string content but re-escape <>& inside string literals as Go marshal does.
    If raw isn't well formed JSON token stream, we output as-is trimmed (caller validated).
    """
    s = str(raw)
    out=[]
    in_str=False
    esc=False
    for ch in s:
        if in_str:
            if esc:
                out.append(ch); esc=False; continue
            if ch=='\\':
                out.append(ch); esc=True; continue
            if ch=='"':
                out.append(ch); in_str=False; continue
            if ch=='<': out.append('\\u003c'); continue
            if ch=='>': out.append('\\u003e'); continue
            if ch=='&': out.append('\\u0026'); continue
            if ch=='\u2028': out.append('\\u2028'); continue
            if ch=='\u2029': out.append('\\u2029'); continue
            out.append(ch)
        else:
            if ch=='"': out.append(ch); in_str=True; continue
            if ch in ' \t\r\n': continue
            out.append(ch)
    return ''.join(out)

def indent_raw_json(raw, indent, level):
    # Use our parser but preserve key order and numbers by parsing and writing with sort_keys=False and JsonNumber.
    try:
        p = JSONParser(str(raw).encode('utf-8','surrogateescape'))
        v = p.parse_value()
        out=[]
        _json_write(v,out,indent,level,sort_keys=False)
        return ''.join(out)
    except Exception:
        return compact_raw_json(raw)

