        dbmap = v["database"]
        if dbmap is None:
            cfg.database = {}
        elif not isinstance(dbmap, dict):
            raise ValueError(f"json: cannot unmarshal {_go_type_name(dbmap)} into Go struct field config.database of type map[string]cmd.database")
        else:
            out = {}
            for name, entry in dbmap.items():
                if entry is None:
                    out[name] = ("", "")
                    continue
                if not isinstance(entry, dict):
                    raise ValueError(f"json: cannot unmarshal {_go_type_name(entry)} into Go struct field config.database of type cmd.database")
                driver = ""
                dsn = ""
                if "driver" in entry:
                    dv = entry["driver"]
                    if dv is None:
                        driver = ""
                    elif isinstance(dv, str) and not isinstance(dv, JsonNumber):
                        driver = dv
                    else:
                        raise ValueError(f"json: cannot unmarshal {_go_type_name(dv)} into Go struct field database.database.driver of type string")
                if "dsn" in entry:
                    dv = entry["dsn"]
                    if dv is None:
                        dsn = ""
                    elif isinstance(dv, str) and not isinstance(dv, JsonNumber):
                        dsn = dv
                    else:
                        raise ValueError(f"json: cannot unmarshal {_go_type_name(dv)} into Go struct field database.database.dsn of type string")
                out[name] = (driver, dsn)
            cfg.database = out
    return cfg

def _os_error_str(e):
    # Map errno to Go-like strings (POSIX strerror lower-case matches GNU mostly)
    if isinstance(e, FileNotFoundError):
        return "no such file or directory"
    if isinstance(e, PermissionError):
        return "permission denied"
    if isinstance(e, IsADirectoryError):
        return "is a directory"
    if isinstance(e, NotADirectoryError):
        return "not a directory"
    if hasattr(e, 'strerror') and e.strerror:
        return e.strerror[:1].lower()+e.strerror[1:]
    return str(e)

def load_config(opts):
    config_path_flag = opts.config
    explicit = config_path_flag != ""
    if explicit:
        path = config_path_flag
    else:
        home = os.environ.get("HOME", "")
        # Go: filepath.Join(home, ".config", "trdsql", "config.json")
        # If home empty, Join returns ".config/trdsql/config.json". If home ends /, join cleans.
        if home:
            path = os.path.join(home, ".config", "trdsql", "config.json")
        else:
            path = os.path.join(".config", "trdsql", "config.json")
    cfg = Config()
    # Check if it's a directory: Go Open succeeds, debug "config found", then decode read error.
    is_dir = False
    try:
        is_dir = os.path.isdir(path)
    except Exception:
        is_dir = False
    if is_dir:
        debug_log(f"config found: {path}")
        if explicit:
            fatal(f"ERROR: [{path}]config error: read {path}: is a directory")
        return cfg, path
    try:
        with open(path, "rb") as f:
            data = f.read()
    except OSError as e:
        debug_log(f"configOpen: open {path}: {_os_error_str(e)}")
        if explicit:
            fatal(f"ERROR: [{path}]no file")
        return cfg, path
    debug_log(f"config found: {path}")
    try:
        cfg = _parse_config_data(data, path)
    except ValueError as e:
        if explicit:
            fatal(f"ERROR: [{path}]config error: {e}")
        return Config(), path
    return cfg, path

def choose_driver(opts, cfg):
    """Returns (driver, dsn). Logs debug database entries, and nonfatal db error when appropriate."""
    selected = opts.db if opts.db != "" else cfg.db
    matched = None
    # Go iterates map randomly; we use file insertion order.
    for name, (driver, dsn) in cfg.database.items():
        marker = ">" if name == selected else " "
        debug_log(f"{marker}[driver: {name}:{driver}:{dsn}]")
        if name == selected and driver != "":
            matched = (driver, dsn)
    if opts.driver == "" and opts.dsn == "":
        if matched is not None:
            return matched[0], matched[1]
        if selected != "":
            error_log(f"ERROR: db[{selected}] does not found")
        return "sqlite3", ""
    else:
        driver = opts.driver if opts.driver != "" else "sqlite3"
        return driver, opts.dsn

