                        dsn = ""
                    elif isinstance(dv, str) and not isinstance(dv, JsonNumber):
                        dsn = dv
                    else:
                        raise ValueError(f"json: cannot unmarshal {_go_type_name(dv)} into Go struct field database.database.dsn of type string")
