        if esc == 'u':
            if len(bs) < i+6 or not all(c in '0123456789abcdefABCDEF' for c in bs[i+2:i+6]):
                raise ValueError("hex")
            out.append(chr(int(bs[i+2:i+6],16))); i+=6; continue
        if esc == 'U':
            if len(bs) < i+10 or not all(c in '0123456789abcdefABCDEF' for c in bs[i+2:i+10]):
                raise ValueError("hex")
