    # LZ4 frame FLG bits: 7-6 version, 5 block independence, 4 block checksum, 3 content size flag, 2 content checksum flag, 1 reserved, 0 dictID flag
    content_size_present=bool(flg & 0x08)
    content_checksum=bool(flg & 0x04)
    dict_present=bool(flg & 0x01)
