        out+=struct.pack('<I', len(chunk)|0x80000000)
        out+=chunk
    out+=struct.pack('<I',0)
    out+=struct.pack('<I', xxhash32(data)&0xFFFFFFFF)
    return bytes(out)

def gzip_compress_go_like(data: bytes) -> bytes:
