def maybe_decompress(data: bytes):
    """Return decompressed bytes if magic found, else data. Raise exceptions with short messages on corrupt compressed data."""
    if data[:3]==b'\x1f\x8b\x08':
        try:
            return gzip.decompress(data)
        except EOFError:
            raise
        except Exception as e:
            # gzip module may raise BadGzipFile etc
            msg=str(e)
            if 'end-of-stream' in msg or 'Compressed file ended' in msg or 'EOF' in msg:
                raise EOFError("unexpected EOF")
            raise
