        try:
            return lzma.decompress(data, format=lzma.FORMAT_XZ)
        except EOFError:
            raise EOFError("unexpected EOF")
        except Exception:
            raise
    if data[:4]==b'\x28\xb5\x2f\xfd':
        return zstd_decompress(data)
    if data[:4]==b'\x04"M\x18':
        return lz4_frame_decompress(data)
    return data

