# ---------------- YAML parser (subset compatible) ----------------
class YAMLError(Exception):
    pass

class YAMLScalar:
    pass

def _yaml_resolve_plain(s):
    t = s.strip()
    if t == "" or t == "~" or t in ("null","Null","NULL"):
        return None
    if t in ("true","True","TRUE"):
        return True
    if t in ("false","False","FALSE"):
        return False
    low = t.lower()
    if low in (".inf","-.inf"):
        return float('inf') if not t.startswith('-') else float('-inf')
    if low == ".nan":
        return float('nan')
    # int
    # hex/binary/octal with prefixes
    body = t
    sign = 1
    if body.startswith(('+','-')):
        if body[0]=='-': sign=-1
        body_nosign = body[1:]
    else:
        body_nosign = body
    try:
        if re.fullmatch(r'0x[0-9a-fA-F_]+', body_nosign):
            return sign * int(body_nosign[2:].replace('_',''),16)
        if re.fullmatch(r'0o[0-7_]+', body_nosign):
            return sign * int(body_nosign[2:].replace('_',''),8)
        if re.fullmatch(r'0b[01_]+', body_nosign):
            return sign * int(body_nosign[2:].replace('_',''),2)
        if re.fullmatch(r'[0-9][0-9_]*', body_nosign):
            # underscores only between digits? just strip
            return sign * int(body_nosign.replace('_',''),10)
    except Exception:
        pass
    # float requires a dot (YAML core-ish + observed)
    # [+-]? ( [0-9][0-9_]*)? \.[0-9_]* ([eE][+-]?[0-9]+)?  with at least one digit somewhere
    if re.fullmatch(r'[+-]?(\.[0-9_]+|[0-9][0-9_]*\.[0-9_]*)([eE][+-]?[0-9]+)?', t):
        try:
            return float(t.replace('_',''))
        except Exception:
            pass
    return t

def _yaml_scalar_to_key(v):
    # Keys converted later via value->string for column names. Use a hashable representation internally if unhashable.
    if isinstance(v, (list,dict)):
        return _yaml_nested_string(v)
    return v

def _yaml_nested_string(v):
    """Nested YAML structures as stored DB string: JSON-like with spaces, keys sorted."""
    if v is None:
        return "null"
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, int):
        return str(v)
    if isinstance(v, float):
        # In nested JSON-ish conversion, Go float formatting differs from DB scalar conversion? Values 1.5 etc; use go_float_g but 1e10 as float is not parsed in YAML.
        return go_float_g(v)
    if isinstance(v, str):
        # Quote as JSON string without HTML escaping
        out=['"']
        for ch in v:
            if ch=='"': out.append('\\"')
            elif ch=='\\': out.append('\\\\')
            elif ch=='\n': out.append('\\n')
            elif ch=='\r': out.append('\\r')
            elif ch=='\t': out.append('\\t')
            elif ord(ch)<0x20: out.append(f'\\u{ord(ch):04x}')
            else: out.append(ch)
        out.append('"')
        return ''.join(out)
    if isinstance(v, list):
        return '[' + ', '.join(_yaml_nested_string(x) for x in v) + ']'
    if isinstance(v, dict):
        items=[]
        for k in sorted(v.keys(), key=lambda x: str(x)):
            ks=_yaml_nested_string(str(k) if not isinstance(k,(list,dict)) else _yaml_nested_string(k))
            items.append(f"{ks}: {_yaml_nested_string(v[k])}")
        return '{' + ', '.join(items) + '}'
    return str(v)

