                # value is block below or None
                val=self._parse_block_value(parent_indent)
                if tag: val=_yaml_apply_tag(val, tag, self)
                if anchor_name: self.anchors[anchor_name]=val
                return val
            # else parse remaining as inline/block in place (fallthrough with rest=remaining)
            rest_no_comment=remaining
            # parse inline then apply
            val=self._parse_inline_or_block_scalar(rest_no_comment, parent_indent, line)
            if tag: val=_yaml_apply_tag(val, tag, self)
            if anchor_name: self.anchors[anchor_name]=val
            return val
        if rest_no_comment=="":
            return self._parse_block_value(parent_indent)
        return self._parse_inline_or_block_scalar(rest_no_comment, parent_indent, line)
    def _parse_block_value(self, parent_indent):
        idx=self._next_sig()
        if idx>=len(self.lines):
            self.idx=idx; return None
        line=self.lines[idx]
