            while pos<len(s) and s[pos] in ' \t': pos+=1
            if pos>=len(s): break
            if s[pos]=='&':
                j=pos+1
                while j<len(s) and s[j] not in ' \t': j+=1
                anchor=s[pos+1:j]; pos=j; continue
            if s[pos]=='!':
                j=pos
                while j<len(s) and s[j] not in ' \t': j+=1
                tag=s[pos:j]; pos=j; continue
            break
