        # Strip trailing blank collected lines that fell after block if they were just separation?
        # Determine how many trailing blank lines from lines consumed beyond last nonblank: they are part of keep/clip logic. We'll keep in collected and chomp handles.
        text_lines=collected
        if style=='|':
            content='\n'.join(text_lines)
