            # Track trailing blank counts
            trailing_blanks=0
            for t in reversed(text_lines):
                if t=="": trailing_blanks+=1
                else: break
            core_lines=text_lines[:len(text_lines)-trailing_blanks] if trailing_blanks else text_lines
            core='\n'.join(core_lines)
            if chomp=='strip':
                return core
            elif chomp=='clip':
                return core+'\n' if core_lines else ''
            else: # keep
                if not core_lines:
                    return '\n'*trailing_blanks
