                else: break
            core_lines=text_lines[:len(text_lines)-trailing_blanks] if trailing_blanks else text_lines
            out=[]
            prev_blank=True
            prev_more=False
            for idx_l, l in enumerate(core_lines):
                if l=="":
                    out.append('\n')
