                return core
            elif chomp=='clip':
                return core+'\n' if core_lines else ''
            else:
                return core+'\n' + ('\n'*trailing_blanks)
    def parse_sequence(self, indent):
        out=[]
        while True:
            idx=self._next_sig()
            if idx>=len(self.lines):
