            orig_line=line
            virt=_YLine(' '*virtual_indent+rest, line.lineno)
            # _YLine computes indent from raw spaces correctly
            self.lines[idx]=virt
            self.idx=idx
            # prefix anchors/tags in rest could be handled by parse_block standalone/mapping incomplete.
            # parse block at virtual indent
            val=self.parse_block(virtual_indent)
            out.append(val)
            # Note: original line replaced; subsequent iterations inspect new lines
        return out
    def parse_standalone(self, indent):
        idx=self.idx
        line=self.lines[idx]
        content=_yaml_strip_comment(line.content).strip()
        self.idx=idx+1
