    def parse_flow_seq(self):
        self.i+=1
        out=[]
        self.skip()
        if self.peek()==']':
            self.i+=1; return out
        while True:
            # parse element, may be single-pair mapping
            elem_start=self.i
            node=self.parse_node(in_flow=True)
            self.skip()
            if self.peek()==':' and not isinstance(node,(dict,)):
                # single pair map in flow sequence
                # Colon's following parsing
                # only if colon not part of plain? parse_node plain already stops before flow colon.
                self.i+=1
                val=self.parse_node(in_flow=True)
                node={_yaml_scalar_to_key(node): val}
            out.append(node)
            self.skip()
            if self.peek()==',':
                self.i+=1; self.skip()
                if self.peek()==']':
                    self.i+=1; break
                continue
            if self.peek()==']':
                self.i+=1; break
            if self.i>=self.n:
                raise YAMLError("sequence not closed")
            raise YAMLError(f"unexpected character {self.peek()!r}")
        return out
    def parse_flow_map(self):
        self.i+=1
        out={}
        self.skip()
        if self.peek()=='}':
            self.i+=1; return out
        while True:
            self.skip()
            key=self.parse_node(in_flow=True)
            self.skip()
            if self.peek()==':':
                self.i+=1
                val=self.parse_node(in_flow=True)
            else:
                val=None
            out[_yaml_scalar_to_key(key)]=val
            self.skip()
            if self.peek()==',':
                self.i+=1; self.skip()
                if self.peek()=='}':
                    self.i+=1; break
                continue
            if self.peek()=='}':
                self.i+=1; break
            if self.i>=self.n:
                raise YAMLError("mapping not closed")
            raise YAMLError(f"unexpected character {self.peek()!r}")
