# ---------------- YAML parser (subset compatible) ----------------
class YAMLError(Exception):
    pass

class YAMLScalar:
    pass

def _yaml_resolve_plain(s):
    t = s.strip()
    if t == "" or t == "~" or t in ("null","Null","NULL"):
        return None
    if t in ("true","True","TRUE"):
        return True
    if t in ("false","False","FALSE"):
        return False
    low = t.lower()
    if low in (".inf","-.inf"):
        return float('inf') if not t.startswith('-') else float('-inf')
    if low == ".nan":
        return float('nan')
    # int
    # hex/binary/octal with prefixes
    body = t
    sign = 1
    if body.startswith(('+','-')):
        if body[0]=='-': sign=-1
        body_nosign = body[1:]
    else:
        body_nosign = body
    try:
        if re.fullmatch(r'0x[0-9a-fA-F_]+', body_nosign):
            return sign * int(body_nosign[2:].replace('_',''),16)
        if re.fullmatch(r'0o[0-7_]+', body_nosign):
            return sign * int(body_nosign[2:].replace('_',''),8)
        if re.fullmatch(r'0b[01_]+', body_nosign):
            return sign * int(body_nosign[2:].replace('_',''),2)
        if re.fullmatch(r'[0-9][0-9_]*', body_nosign):
            # underscores only between digits? just strip
            return sign * int(body_nosign.replace('_',''),10)
    except Exception:
        pass
    # float requires a dot (YAML core-ish + observed)
    # [+-]? ( [0-9][0-9_]*)? \.[0-9_]* ([eE][+-]?[0-9]+)?  with at least one digit somewhere
    if re.fullmatch(r'[+-]?(\.[0-9_]+|[0-9][0-9_]*\.[0-9_]*)([eE][+-]?[0-9]+)?', t):
        try:
            return float(t.replace('_',''))
        except Exception:
            pass
    return t

def _yaml_scalar_to_key(v):
    # Keys converted later via value->string for column names. Use a hashable representation internally if unhashable.
    if isinstance(v, (list,dict)):
        return _yaml_nested_string(v)
    return v

def _yaml_nested_string(v):
    """Nested YAML structures as stored DB string: JSON-like with spaces, keys sorted."""
    if v is None:
        return "null"
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, int):
        return str(v)
    if isinstance(v, float):
        # In nested JSON-ish conversion, Go float formatting differs from DB scalar conversion? Values 1.5 etc; use go_float_g but 1e10 as float is not parsed in YAML.
        return go_float_g(v)
    if isinstance(v, str):
        # Quote as JSON string without HTML escaping
        out=['"']
        for ch in v:
            if ch=='"': out.append('\\"')
            elif ch=='\\': out.append('\\\\')
            elif ch=='\n': out.append('\\n')
            elif ch=='\r': out.append('\\r')
            elif ch=='\t': out.append('\\t')
            elif ord(ch)<0x20: out.append(f'\\u{ord(ch):04x}')
            else: out.append(ch)
        out.append('"')
        return ''.join(out)
    if isinstance(v, list):
        return '[' + ', '.join(_yaml_nested_string(x) for x in v) + ']'
    if isinstance(v, dict):
        items=[]
        for k in sorted(v.keys(), key=lambda x: str(x)):
            ks=_yaml_nested_string(str(k) if not isinstance(k,(list,dict)) else _yaml_nested_string(k))
            items.append(f"{ks}: {_yaml_nested_string(v[k])}")
        return '{' + ', '.join(items) + '}'
    return str(v)

class _YLine:
    __slots__=('raw','indent','content','lineno')
    def __init__(self, raw, lineno):
        self.raw=raw
        self.lineno=lineno
        # indent count spaces; tabs count as 1? (keep as spaces expanded?)
        i=0
        while i<len(raw) and raw[i]==' ':
            i+=1
        self.indent=i
        self.content=raw[i:]
    def __repr__(self):
        return f"YLine({self.indent},{self.content!r})"

def _yaml_is_comment_or_blank(line):
    s=line.content.strip()
    return s=="" or s.startswith('#')

def _yaml_strip_comment(s):
    """Strip trailing comment starting with space+ # outside quotes/flow? Simple scan."""
    in_s=False; in_d=False; esc=False
    i=0
    while i<len(s):
        ch=s[i]
        if in_d:
            if esc: esc=False
            elif ch=='\\': esc=True
            elif ch=='"': in_d=False
        elif in_s:
            if ch=="'":
                if i+1<len(s) and s[i+1]=="'":
                    i+=2; continue
                in_s=False
        else:
            if ch=='"': in_d=True
            elif ch=="'": in_s=True
            elif ch=='#' and (i==0 or s[i-1] in ' \t'):
                return s[:i].rstrip()
        i+=1
    return s

class _FlowParser:
    def __init__(self, text, anchors, parent):
        self.s=text
        self.i=0
        self.n=len(text)
        self.anchors=anchors
        self.parent=parent
    def skip(self):
        while self.i<self.n:
            if self.s[self.i] in ' \t\r\n':
                self.i+=1; continue
            if self.s[self.i]=='#':
                # comment to end line
                while self.i<self.n and self.s[self.i]!='\n': self.i+=1
                continue
            break
    def peek(self):
        return self.s[self.i] if self.i<self.n else ''
    def parse(self):
        self.skip()
        v=self.parse_node()
        self.skip()
        return v
    def parse_node(self, in_flow=False):
        self.skip()
        if self.i>=self.n:
            return None
        # prefixes anchor/tag/alias
        force_tag=None
        anchor_name=None
        while True:
            self.skip()
            if self.i<self.n and self.s[self.i]=='&':
                self.i+=1
                start=self.i
                while self.i<self.n and self.s[self.i] not in ' \t\r\n,]}': self.i+=1
                anchor_name=self.s[start:self.i]
                continue
            if self.i<self.n and self.s[self.i]=='*':
                self.i+=1
                start=self.i
                while self.i<self.n and self.s[self.i] not in ' \t\r\n,]}': self.i+=1
                name=self.s[start:self.i]
                return self.anchors.get(name)
            if self.i<self.n and self.s[self.i]=='!':
                start=self.i
                while self.i<self.n and self.s[self.i] not in ' \t\r\n': self.i+=1
                tag=self.s[start:self.i]
                force_tag=tag
                continue
            break
        self.skip()
        if self.i>=self.n:
            result=None
            if anchor_name: self.anchors[anchor_name]=result
            return result
        c=self.s[self.i]
        if c=='[':
            result=self.parse_flow_seq()
        elif c=='{':
            result=self.parse_flow_map()
        elif c=='"':
            result=self.parse_double()
        elif c=="'":
            result=self.parse_single()
        else:
            result=self.parse_plain(in_flow=in_flow)
        if force_tag:
            result=_yaml_apply_tag(result, force_tag, self.parent)
        if anchor_name:
            self.anchors[anchor_name]=result
        return result
    def parse_flow_seq(self):
        self.i+=1
        out=[]
        self.skip()
        if self.peek()==']':
            self.i+=1; return out
        while True:
            # parse element, may be single-pair mapping
            elem_start=self.i
            node=self.parse_node(in_flow=True)
            self.skip()
            if self.peek()==':' and not isinstance(node,(dict,)):
                # single pair map in flow sequence
                # Colon's following parsing
                # only if colon not part of plain? parse_node plain already stops before flow colon.
                self.i+=1
                val=self.parse_node(in_flow=True)
                node={_yaml_scalar_to_key(node): val}
            out.append(node)
            self.skip()
            if self.peek()==',':
                self.i+=1; self.skip()
                if self.peek()==']':
                    self.i+=1; break
                continue
            if self.peek()==']':
                self.i+=1; break
            if self.i>=self.n:
                raise YAMLError("sequence not closed")
            raise YAMLError(f"unexpected character {self.peek()!r}")
        return out
    def parse_flow_map(self):
        self.i+=1
        out={}
        self.skip()
        if self.peek()=='}':
            self.i+=1; return out
        while True:
            self.skip()
            key=self.parse_node(in_flow=True)
            self.skip()
            if self.peek()==':':
                self.i+=1
                val=self.parse_node(in_flow=True)
            else:
                val=None
            out[_yaml_scalar_to_key(key)]=val
            self.skip()
            if self.peek()==',':
                self.i+=1; self.skip()
                if self.peek()=='}':
                    self.i+=1; break
                continue
            if self.peek()=='}':
                self.i+=1; break
            if self.i>=self.n:
                raise YAMLError("mapping not closed")
            raise YAMLError(f"unexpected character {self.peek()!r}")
        return out
    def parse_single(self):
        self.i+=1
        out=[]
        while self.i<self.n:
            c=self.s[self.i]
            if c=="'":
                if self.i+1<self.n and self.s[self.i+1]=="'":
                    out.append("'"); self.i+=2; continue
                self.i+=1; return ''.join(out)
            out.append(c); self.i+=1
        raise YAMLError("unterminated single-quoted string")
    def parse_double(self):
        self.i+=1
        out=[]
        while self.i<self.n:
            c=self.s[self.i]
            if c=='"':
                self.i+=1; return ''.join(out)
            if c=='\\':
                if self.i+1>=self.n: raise YAMLError("unterminated escape")
                e=self.s[self.i+1]; self.i+=2
                mp={'0':'\0','a':'\a','b':'\b','t':'\t','\t':'\t','n':'\n','v':'\v','f':'\f','r':'\r','e':'\x1b','"':'"','\\':'\\','/':'/',' ':' ','_':'\u00a0','N':'\u0085','L':'\u2028','P':'\u2029'}
                if e in mp: out.append(mp[e])
                elif e=='x':
                    if self.i+2>self.n: raise YAMLError("bad hex escape")
                    out.append(chr(int(self.s[self.i:self.i+2],16))); self.i+=2
                elif e=='u':
                    if self.i+4>self.n: raise YAMLError("bad unicode escape")
                    out.append(chr(int(self.s[self.i:self.i+4],16))); self.i+=4
                elif e=='U':
                    if self.i+8>self.n: raise YAMLError("bad unicode escape")
                    out.append(chr(int(self.s[self.i:self.i+8],16))); self.i+=8
                elif e=='\n':
                    # line continuation: skip following spaces
                    while self.i<self.n and self.s[self.i] in ' \t': self.i+=1
                else:
                    # Unknown escape: YAML would error; be lenient and produce char
                    out.append(e)
                continue
            out.append(c); self.i+=1
        raise YAMLError("unterminated double-quoted string")
    def parse_plain(self, in_flow=False):
        start=self.i
        # Determine end
        i=self.i
        depth=0
        # Plain scalar in flow ends at , ] } at depth 0 or : followed by delimiter/space or colon at flow contexts
        # In non-flow (inline remainder), it takes rest, but comments handled by caller/strip.
        while i<self.n:
            ch=self.s[i]
            if in_flow:
                if ch in ',]}' and depth==0:
                    break
                if ch==':' :
                    nxt=self.s[i+1] if i+1<self.n else ''
                    if nxt in ('', ' ', '\t', '\n', ',',']','}'):
                        break
                if ch=='#' and i>start and self.s[i-1] in ' \t':
                    break
            i+=1
        token=self.s[start:i].strip()
        self.i=i
        # Multi-line plain folding inside flow string (newlines become spaces)
        # Collapse internal whitespace sequences containing newline to a single space for plain scalars (approx YAML folding for simple cases)
        if '\n' in token:
            # Fold: single newlines -> space, multiple -> keep (n-1) newlines ; simplify
            token=re.sub(r'[ \t]*\n[ \t]*', lambda m: '\n' if '\n\n' in m.group(0) else ' ', token)
            token=token.strip()
        return _yaml_resolve_plain(token)

def _yaml_apply_tag(v, tag, parent=None):
    if tag in ('!!str','!<tag:yaml.org,2002:str>'):
        if isinstance(v,str): return v
        if v is None: return ""
        if isinstance(v,bool): return "true" if v else "false"
        return _scalar_to_string_for_db(v)
    if tag.startswith('!!int'):
        if isinstance(v,str):
            r=_yaml_resolve_plain(v)
            return r if isinstance(r,int) and not isinstance(r,bool) else v
        return v
    if tag.startswith('!!float'):
        if isinstance(v,str):
            try: return float(v)
            except Exception: return v
        return v
    if tag.startswith('!!bool'):
        if isinstance(v,str):
            r=_yaml_resolve_plain(v)
            return r if isinstance(r,bool) else v
    if tag.startswith('!!null'):
        return None
    # custom tags: keep underlying as string if scalar was string, else value
    return v

def _scalar_to_string_for_db(v):
    if v is None:
        return None
    if isinstance(v,bool):
        return "true" if v else "false"
    if isinstance(v,int):
        return str(v)
    if isinstance(v,float):
        return go_float_g(v)
    if isinstance(v,str):
        return v
    return str(v)

class _YAMLDocParser:
    def __init__(self, lines):
        self.lines=lines  # list[_YLine]
        self.idx=0
        self.anchors={}
    def _next_sig(self, start=None):
        i=self.idx if start is None else start
        while i<len(self.lines) and _yaml_is_comment_or_blank(self.lines[i]):
            i+=1
        return i
    def parse(self):
        idx=self._next_sig(0)
        if idx>=len(self.lines):
            return None
        self.idx=idx
        val=self.parse_block(self.lines[idx].indent)
        return val
    def parse_block(self, min_indent):
        idx=self._next_sig()
        if idx>=len(self.lines):
            self.idx=idx; return None
        self.idx=idx
        line=self.lines[idx]
        if line.indent < min_indent:
            return None
        indent=line.indent
        content=line.content
        # anchors/tags alone on line?
        # Sequence?
        if content=='-' or content.startswith('- ') or content.startswith('-\t'):
            return self.parse_sequence(indent)
        # Mapping?
        if self._find_mapping(content) is not None:
            return self.parse_mapping(indent)
        # Otherwise a standalone node (flow/ scalar / block scalar / quoted)
        return self.parse_standalone(indent)
    def _find_mapping(self, content):
        """Return (key_raw_end_index, colon_index) if content starts a mapping, else None.
        Key might be quoted.
        """
        s=content
        if s.startswith('? ') or s=='?':
            return None
        # Quoted key
        if s and s[0] in ('"',"'"):
            # parse quoted token
            try:
                fp=_FlowParser(s, self.anchors, self)
                # We only need length: use parse_single/double limited
                if s[0]=='"': fp.parse_double()
                else: fp.parse_single()
                j=fp.i
                while j<len(s) and s[j] in ' \t': j+=1
                if j<len(s) and s[j]==':' and (j+1>=len(s) or s[j+1] in ' \t'):
                    return (j, j)
                return None
            except Exception:
                return None
        # Scan for colon followed by space/EOL, outside flow
        depth=0; in_s=False; in_d=False; esc=False
        i=0
        while i<len(s):
            ch=s[i]
            if in_d:
                if esc: esc=False
                elif ch=='\\': esc=True
                elif ch=='"': in_d=False
            elif in_s:
                if ch=="'":
                    if i+1<len(s) and s[i+1]=="'": i+=2; continue
                    in_s=False
            else:
                if ch=='"': in_d=True
                elif ch=="'": in_s=True
                elif ch in '[{': depth+=1
                elif ch in ']}': depth-=1
                elif ch==':' and depth==0:
                    if i+1>=len(s) or s[i+1] in ' \t':
                        # Ensure key part isn't empty? (key may be empty string token '' handled above; plain empty before colon could be like ': value' with null key)
                        return (i,i)
                elif ch=='#' and i>0 and s[i-1] in ' \t':
                    break
            i+=1
        return None
    def parse_mapping(self, indent):
        out={}
        positions={}
        merge_sources=[]
        while True:
            idx=self._next_sig()
            if idx>=len(self.lines):
                self.idx=idx; break
            line=self.lines[idx]
            if line.indent!=indent:
                break
            found=self._find_mapping(line.content)
            if found is None:
                break
            colon_idx,_ = found
            key_raw=line.content[:colon_idx].strip()
            rest=line.content[colon_idx+1:]
            # rest: strip leading spaces/tabs (one separation)
            rest_stripped=rest.lstrip(' \t')
            key=_FlowParser(key_raw, self.anchors, self).parse() if key_raw!="" else None
            # _FlowParser parse for plain keys resolves types; quoted remains string.
            key_for_dict=_yaml_scalar_to_key(key)
            # duplicate detection for hashable keys (goccy duplicate error)
            # Only detect duplicate string-like keys after resolution
            dup_key = key_for_dict
            if dup_key in positions and dup_key != '<<':
                prev_lineno=positions[dup_key]
                # Build an error resembling goccy
                cur_no=line.lineno+1
                prev_no=prev_lineno+1
                # Snippet generation made by raising error with a special attribute; caller can use str
                raise YAMLError(_yaml_dup_error(self.lines, line.lineno, prev_lineno, str(key_for_dict)))
            positions[dup_key]=line.lineno
            self.idx=idx+1
            value=self._parse_value_after_key(rest_stripped, indent, line)
            if key_for_dict=='<<':
                # merge
                if isinstance(value, dict):
                    merge_sources.append(value)
                elif isinstance(value, list):
                    for item in value:
                        if isinstance(item, dict): merge_sources.append(item)
                continue
            out[key_for_dict]=value
        # apply merges (explicit keys win)
        if merge_sources:
            merged={}
            for src in merge_sources:
                for k,v in src.items():
                    if k not in merged: merged[k]=v
            for k,v in out.items(): merged[k]=v
            out=merged
        return out
    def _parse_value_after_key(self, rest, parent_indent, line):
        # rest has no leading spaces
        rest_no_comment=_yaml_strip_comment(rest).rstrip()
        # Anchor/tag only -> node on following lines or null
        prefix_info=self._extract_prefix(rest_no_comment)
        if prefix_info is not None:
            anchor_name, tag, remaining = prefix_info
            if remaining=="":
                # value is block below or None
                val=self._parse_block_value(parent_indent)
                if tag: val=_yaml_apply_tag(val, tag, self)
                if anchor_name: self.anchors[anchor_name]=val
                return val
            # else parse remaining as inline/block in place (fallthrough with rest=remaining)
            rest_no_comment=remaining
            # parse inline then apply
            val=self._parse_inline_or_block_scalar(rest_no_comment, parent_indent, line)
            if tag: val=_yaml_apply_tag(val, tag, self)
            if anchor_name: self.anchors[anchor_name]=val
            return val
        if rest_no_comment=="":
            return self._parse_block_value(parent_indent)
        return self._parse_inline_or_block_scalar(rest_no_comment, parent_indent, line)
    def _parse_block_value(self, parent_indent):
        idx=self._next_sig()
        if idx>=len(self.lines):
            self.idx=idx; return None
        line=self.lines[idx]
        # block sequence may be at same indent as key
        if line.indent>=parent_indent and (line.content=='-' or line.content.startswith('- ') or line.content.startswith('-\t')):
            # Using its own indent (could be == parent)
            return self.parse_block(line.indent)
        if line.indent>parent_indent:
            return self.parse_block(line.indent)
        return None
    def _parse_inline_or_block_scalar(self, rest, parent_indent, line):
        # block scalar indicators
        if rest and rest[0] in ('|','>'):
            return self._parse_block_scalar(rest, parent_indent)
        # If rest looks like a sequence entry on same line after key? e.g. key: - a (rare). Treat as one-item? Actual YAML requires sequence indent; flow parser plain token '- a' would just scalar. Leave.
        # Gather continuation lines if flow unclosed or quotes unclosed
        text=rest
        # Collect while unbalanced
        while self._flow_unbalanced(text):
            nxt=self._next_sig()
            if nxt>=len(self.lines):
                break
            # consume raw line (not just sig? include its raw content)
            # Use idx sequence including comments? use next raw line index self.idx (may be comment lines)
            # We'll consume from self.idx onwards literal line
            if self.idx>=len(self.lines): break
            text += '\n' + self.lines[self.idx].raw
            self.idx+=1
        # Plain scalar multiline continuation: following lines with indent > parent_indent that don't look like new mapping at deeper level? In YAML, continuation plain lines are indented more than key.
        # Only apply if text is a plain scalar (not starting with flow/quote)
        if text and text[0] not in ('[','{','"',"'"):
            # Only plain scalars (including anchors already stripped)
            parts=[text]
            while True:
                nxt=self._next_sig()
                if nxt>=len(self.lines): break
                nline=self.lines[nxt]
                if nline.indent<=parent_indent: break
                # If line is a mapping at deeper indent, that would be an error in strict YAML; treat as continuation text (fold)
                # Consume it
                parts.append(nline.content.strip())
                self.idx=nxt+1
            if len(parts)>1:
                text=' '.join(parts)
        return _FlowParser(text, self.anchors, self).parse()
    def _flow_unbalanced(self, text):
        depth_bracket=0; depth_brace=0; in_s=False; in_d=False; esc=False
        i=0
        while i<len(text):
            ch=text[i]
            if in_d:
                if esc: esc=False
                elif ch=='\\': esc=True
                elif ch=='"': in_d=False
            elif in_s:
                if ch=="'":
                    if i+1<len(text) and text[i+1]=="'": i+=2; continue
                    in_s=False
            else:
                if ch=='"': in_d=True
                elif ch=="'": in_s=True
                elif ch=='[': depth_bracket+=1
                elif ch==']': depth_bracket-=1
                elif ch=='{': depth_brace+=1
                elif ch=='}': depth_brace-=1
            i+=1
        return in_s or in_d or depth_bracket>0 or depth_brace>0
    def _extract_prefix(self, rest):
        # If rest is like '&a', '&a !!str', '!!str', '*a' alone etc, or prefixed node, return info.
        # We only handle if first token starts with &,*,!
        if not rest or rest[0] not in ('&','!','*'):
            return None
        # Tokenize prefix words
        tokens=[]
        s=rest
        pos=0
        anchor=None; tag=None
        while pos<len(s):
            # skip spaces
            while pos<len(s) and s[pos] in ' \t': pos+=1
            if pos>=len(s): break
            if s[pos]=='&':
                j=pos+1
                while j<len(s) and s[j] not in ' \t': j+=1
                anchor=s[pos+1:j]; pos=j; continue
            if s[pos]=='!':
                j=pos
                while j<len(s) and s[j] not in ' \t': j+=1
                tag=s[pos:j]; pos=j; continue
            break
        if anchor is None and tag is None:
            return None
        remaining=s[pos:].lstrip(' \t')
        return (anchor, tag, remaining)
    def _parse_block_scalar(self, header, parent_indent):
        style=header[0]
        rest=header[1:].strip()
        chomp='clip'
        explicit_indent=None
        # parse indicators in rest before comment
        # Remove comment
        rest=_yaml_strip_comment(rest)
        for ch in rest:
            if ch=='-': chomp='strip'
            elif ch=='+': chomp='keep'
