        collected=[]
        block_indent=None
        if explicit_indent is not None:
            block_indent=parent_indent+explicit_indent
        i=self.idx
        while i<len(self.lines):
            line=self.lines[i]
            if line.content.strip()=="":
                # blank line: include empty, advance tentatively (may include trailing blanks beyond block? include until nonblank determines)
                collected.append("")
                i+=1
                continue
            if block_indent is None:
                if line.indent<=parent_indent:
                    break
                block_indent=line.indent
            if line.indent<block_indent:
                break
            # remove block_indent spaces
            raw=line.raw
            if len(raw)>=block_indent:
