        # Strip trailing blank collected lines that fell after block if they were just separation?
        # Determine how many trailing blank lines from lines consumed beyond last nonblank: they are part of keep/clip logic. We'll keep in collected and chomp handles.
        text_lines=collected
        if style=='|':
            content='\n'.join(text_lines)
            # If any content, lines join doesn't have final \n; we add based on chomp later
            # Track trailing blank counts
            trailing_blanks=0
            for t in reversed(text_lines):
                if t=="": trailing_blanks+=1
                else: break
            core_lines=text_lines[:len(text_lines)-trailing_blanks] if trailing_blanks else text_lines
            core='\n'.join(core_lines)
            if chomp=='strip':
                return core
            elif chomp=='clip':
                return core+'\n' if core_lines else ''
            else: # keep
                if not core_lines:
                    return '\n'*trailing_blanks
                return core+'\n' + ('\n'*trailing_blanks)
        else:
            # folded
            # Separate trailing blanks
            trailing_blanks=0
            for t in reversed(text_lines):
                if t=="": trailing_blanks+=1
                else: break
            core_lines=text_lines[:len(text_lines)-trailing_blanks] if trailing_blanks else text_lines
            out=[]
