    # cur line raw indent plus 7 (?) From observed: `       ^` (7 spaces before caret)
    caret = ' ' * (7 + lines[cur_lin_idx].indent) + '^'
    snippet.append(caret)
    return f"[{cur_no}:{lines[cur_lin_idx].indent+1}] mapping key \"{key}\" already defined at [{prev_no}:{lines[prev_lin_idx].indent+1}]\n" + "\n".join(snippet)

def parse_yaml_documents(text):
    """Return list of document values. Raise YAMLError on errors. Empty text returns [] (EOF sentinel handled by caller)."""
    if isinstance(text, bytes):
        text=text.decode('utf-8','surrogateescape')
    raw_lines=text.splitlines()
    docs=[]
    cur_lines=[]
    # Split on document markers at col0
    def flush():
        # Only add if cur_lines has any non-comment/nonblank? But a doc with only comments is a document null in some contexts; reference for comment-only gives invalid names on first doc value None? We'll treat a doc segment that was explicit (seen marker) as a doc; initial empty no doc.
        pass
    segments=[]
    cur=[]
    had_marker=False
    for raw in raw_lines:
        if re.match(r'^---($|[ \t])', raw):
            segments.append(cur)
            cur=[]
            had_marker=True
            after=raw[3:].lstrip(' \t')
            if after:
                cur.append(after)
            continue
        if re.match(r'^\.\.\.($|[ \t])', raw):
            segments.append(cur)
            cur=[]
            had_marker=True
            continue
        if raw.startswith('%') and not cur:
            # directive line before doc start; skip
            continue
        cur.append(raw)
    segments.append(cur)
    # Segments: first segment before first marker may be empty - drop only if its all blank AND had_marker and it's first
    results=[]
    for si,seg in enumerate(segments):
        # check if seg is all blank/comment
        if all((not l.strip()) or l.lstrip().startswith('#') for l in seg):
            if si==0 and not had_marker:
                # no documents
                continue
            if si==0 and had_marker:
                continue
            # An explicit empty document yields None
            # Only keep if there was a separator creating it (segments after first)
            results.append(None)
            continue
        lines=[_YLine(l, i) for i,l in enumerate(seg)]
        # For error line numbers across docs, approximate local to doc segment (goccy uses whole file lines). To keep duplicate snippet etc relative, okay.
        # But to improve dup error line numbers in whole file when docs are concatenated with no markers, single segment line nos are file lines.
        parser=_YAMLDocParser(lines)
        results.append(parser.parse())
    return results

