        then_node=self.parse_pipe_no_comma()
        elifs=[]
        else_node=None
        while self.consume_word('elif'):
            c=self.parse_pipe_no_comma(); 
            if not self.consume_word('then'):self.err("expected then")
            t=self.parse_pipe_no_comma(); elifs.append((c,t))
        if self.consume_word('else'):
            else_node=self.parse_pipe_no_comma()
        if not self.consume_word('end'):self.err("expected end")
        return ('if',cond,then_node,elifs,else_node)
    def parse_reduce(self):
        self.consume_word('reduce'); src=self.parse_postfix()
        if not self.consume_word('as'):self.err("expected as")
        var=self.parse_variable_name(); self.expect('('); init=self.parse_pipe_no_comma(); self.expect(';'); update=self.parse_pipe_no_comma(); self.expect(')')
        return ('reduce',src,var,init,update)
    def parse_foreach(self):
        self.consume_word('foreach'); src=self.parse_postfix()
        if not self.consume_word('as'):self.err("expected as")
        var=self.parse_variable_name(); self.expect('('); init=self.parse_pipe_no_comma(); self.expect(';'); update=self.parse_pipe_no_comma()
        extract=None
        if self.consume(';'): extract=self.parse_pipe_no_comma()
        self.expect(')')
        return ('foreach',src,var,init,update,extract)
    def parse_object_construct(self):
        self.expect('{')
        entries=[]
        self.skip()
        if self.consume('}'):return ('object_construct',entries)
        while True:
            self.skip()
            key_node=None; key_string=None; shorthand_field=None
            if self.i<self.n and self.s[self.i]=='(':
                self.i+=1; key_node=self.parse_pipe(); self.expect(')')
            elif self.i<self.n and self.s[self.i]=='"':
                sn=self.parse_string_literal(); key_node=sn
            elif self.i<self.n and self.s[self.i]=='.':
                # .field shorthand or key
                # consume .field
                self.i+=1; shorthand_field=self.parse_field_name_after_dot(); key_string=shorthand_field
            elif self.i<self.n and self.s[self.i]=='$':
                var=self.parse_variable_name(); key_string=var; shorthand_field=('var',var)
            else:
                # keyword / identifier
                ident=self.parse_identifier(); key_string=ident; shorthand_field=ident
            self.skip()
            if self.consume(':'):
                value=self.parse_pipe_no_comma()
            else:
                # shorthand
                if isinstance(shorthand_field,tuple):
                    value=shorthand_field
                elif shorthand_field is not None:
                    value=('field',shorthand_field)
                elif key_node is not None:
                    # {(key)} means get field by key expr; approximate as index
                    value=('index_suffix',('identity',),('index',key_node))
                else:
                    value=('identity',)
            entries.append((key_string,key_node,value))
            self.skip()
            if self.consume(','):
                continue
            self.expect('}');break
        return ('object_construct',entries)

# Evaluation
def jq_eval(node, value, env=None, defs=None):
    if env is None: env={}
    if defs is None: defs={}
    typ=node[0]
    if typ=='identity':
        yield value; return
    if typ=='literal':
        yield node[1]; return
    if typ=='string':
        parts=node[1]
        if not parts:
            yield ""; return
        # String interpolation yields one string per combination of expr outputs (usually first?). jq string interpolation uses each output? It constructs strings from each output of expression cartesian.
        # Implement recursive
        def rec(idx, cur):
            if idx>=len(parts):
                yield cur; return
            kind,part=parts[idx]
            if kind=='str':
                yield from rec(idx+1, cur+part)
            else:
                for out in jq_eval(part, value, env, defs):
                    yield from rec(idx+1, cur+_jq_to_string(out))
        yield from rec(0,""); return
    if typ=='var':
        name=node[1]
        if name=='ENV':
            yield dict(os.environ); return
        if name=='__progname':
            yield "jq"; return
        if name in env:
            yield env[name]; return
        raise JqError(f"variable not defined: ${name}/0" if False else f"${name} is not defined")
    if typ=='field':
        yield _jq_field(value,node[1]); return
    if typ=='field_suffix':
        for v in jq_eval(node[1],value,env,defs):
            yield _jq_field(v,node[2]); return
    if typ=='index_suffix':
        for v in jq_eval(node[1],value,env,defs):
            yield from _jq_apply_suffix(v,node[2],env,defs)
        return
    if typ=='recurse_descent':
        yield from _jq_recurse(value); return
    if typ=='optional':
        try:
            yield from jq_eval(node[1],value,env,defs)
        except JqError:
            return
        return
    if typ=='pipe':
        for mid in jq_eval(node[1],value,env,defs):
            yield from jq_eval(node[2],mid,env,defs)
        return
    if typ=='comma':
        for item in node[1]:
            yield from jq_eval(item,value,env,defs)
        return
    if typ=='bind':
        _,src,vars_,rest=node
        for out in jq_eval(src,value,env,defs):
            env2=dict(env)
            for vn in vars_:
                if vn: env2[vn]=out
            yield from jq_eval(rest,value,env2,defs)
        return
    if typ=='alt':
        produced=False
        try:
            for out in jq_eval(node[1],value,env,defs):
                if jq_truthy(out):
                    produced=True; yield out
        except JqError:
            pass
        if not produced:
            yield from jq_eval(node[2],value,env,defs)
        return
    if typ in ('and','or'):
        for a in jq_eval(node[1],value,env,defs):
            for b in jq_eval(node[2],value,env,defs):
                yield (jq_truthy(a) and jq_truthy(b)) if typ=='and' else (jq_truthy(a) or jq_truthy(b))
        return
    if typ=='cmp':
        _,op,left,right=node
        for a in jq_eval(left,value,env,defs):
            for b in jq_eval(right,value,env,defs):
                c=jq_compare(a,b)
                if op=='==':yield c==0
                elif op=='!=':yield c!=0
                elif op=='<':yield c<0
                elif op=='<=':yield c<=0
                elif op=='>':yield c>0
                elif op=='>=':yield c>=0
        return
    if typ=='bin':
        _,op,left,right=node
        for a in jq_eval(left,value,env,defs):
            for b in jq_eval(right,value,env,defs):
                yield _jq_arith(op,a,b)
        return
    if typ=='neg':
        for a in jq_eval(node[1],value,env,defs):
            n=jq_num_value(a)
            if n is None: raise JqError(f"cannot negate: {jq_type_desc(a)}")
            yield -n
        return
    if typ=='array_construct':
        inner=node[1]
        if inner is None:
            yield []; return
        yield list(jq_eval(inner,value,env,defs)); return
    if typ=='object_construct':
        entries=node[1]
        # Cartesian product of entries values/keys
        def rec(idx, cur):
            if idx>=len(entries):
                yield dict(cur); return
            key_str,key_node,val_node=entries[idx]
            # key outputs
            if key_node is not None:
                key_vals=list(jq_eval(key_node,value,env,defs))
            else:
                key_vals=[key_str]
            val_vals=list(jq_eval(val_node,value,env,defs))
            for kv in key_vals:
                ks=kv if isinstance(kv,str) and not isinstance(kv,JsonNumber) else _jq_to_string(kv) if not isinstance(kv,str) else kv
                if not isinstance(ks,str):
                    raise JqError(f"expected a string for object key but got: {jq_type_desc(kv)}")
                for vv in val_vals:
                    cur2=dict(cur); cur2[ks]=vv
                    yield from rec(idx+1,cur2)
        yield from rec(0,{}); return
    if typ=='if':
        _,cond,then_node,elifs,else_node=node
        for cv in jq_eval(cond,value,env,defs):
            if jq_truthy(cv):
                yield from jq_eval(then_node,value,env,defs)
            else:
                handled=False
                for (ec,et) in elifs:
                    for ev in jq_eval(ec,value,env,defs):
                        if jq_truthy(ev):
                            yield from jq_eval(et,value,env,defs); handled=True
                    if handled:break
                if not handled and else_node is not None:
                    yield from jq_eval(else_node,value,env,defs)
        return
    if typ=='try':
        _,body,catch=node
        try:
            yield from jq_eval(body,value,env,defs)
        except JqError as e:
            if catch is not None:
                yield from jq_eval(catch,str(e),env,defs)
            return
        return
    if typ=='reduce':
        _,src,var,init,update=node
        state=list(jq_eval(init,value,env,defs))
        if not state:return
        cur=state[0]
        for item in jq_eval(src,value,env,defs):
            env2=dict(env); env2[var]=item
            nxt=list(jq_eval(update,cur,env2,defs))
            if nxt:cur=nxt[0]
        yield cur; return
    if typ=='foreach':
        _,src,var,init,update,extract=node
        state=list(jq_eval(init,value,env,defs))
        if not state:return
        cur=state[0]
        for item in jq_eval(src,value,env,defs):
            env2=dict(env); env2[var]=item
            nxt=list(jq_eval(update,cur,env2,defs))
            if nxt:cur=nxt[0]
            if extract is not None:
                yield from jq_eval(extract,cur,env2,defs)
            else:
                yield cur
        return
    if typ=='func':
        yield from _jq_call(node[1],node[2],value,env,defs); return
    raise JqError(f"unsupported jq node {typ}")

def _jq_to_string(v):
    if isinstance(v,str) and not isinstance(v,JsonNumber): return v
    if v is None:return "null"
    return go_json_marshal_compact(v)

def _jq_field(v,key):
    if v is None:return None
    if isinstance(v,dict):return v.get(key,None)
    raise JqError(f"expected an object but got: {jq_type_desc(v)}")

def _jq_apply_suffix(v,suffix,env,defs):
    kind=suffix[0]
    if kind=='iter':
        if isinstance(v,list):
            yield from v; return
        if isinstance(v,dict):
            for k in sorted(v.keys(),key=lambda x:str(x)):yield v[k]
            return
        raise JqError(f"cannot iterate over: {jq_type_desc(v)}")
    if kind=='index':
        # index expr evaluated against original input? In jq, .[expr] evaluates expr against input v (same).
        idx_vals=list(jq_eval(suffix[1],v,env,defs))
        for idx in idx_vals:
            yield _jq_index(v,idx)
        return
    if kind=='slice':
        _,start_node,end_node=suffix
        starts=[None] if start_node is None else list(jq_eval(start_node,v,env,defs))
        ends=[None] if end_node is None else list(jq_eval(end_node,v,env,defs))
        for s in starts:
            for e in ends:
                yield _jq_slice(v,s,e)
        return

def _jq_index(v,idx):
    if v is None:return None
    if isinstance(idx,str) and not isinstance(idx,JsonNumber):
        return _jq_field(v,idx)
    n=jq_num_value(idx)
    if n is not None:
        if isinstance(n,float):
            # jq index must be integer? gojq trims?
            if not n.is_integer():
                raise JqError(f"array index must be an integer")
            n=int(n)
        if isinstance(v,list):
            i=n if n>=0 else len(v)+n
            if 0<=i<len(v):return v[i]
            return None
        if isinstance(v,str):
            chars=list(v)
            i=n if n>=0 else len(chars)+n
            if 0<=i<len(chars):return chars[i]
            return None
        raise JqError(f"expected an array but got: {jq_type_desc(v)}")
    raise JqError(f"expected a string or number for indexing")

def _jq_slice(v,s,e):
    if v is None:return None
    def toint(x):
        if x is None:return None
        n=jq_num_value(x)
        if n is None:raise JqError("slice index must be a number")
        return int(n)
    si=toint(s); ei=toint(e)
    if isinstance(v,list):
        return v[si:ei]
    if isinstance(v,str):
        chars=list(v); return ''.join(chars[si:ei])
    raise JqError(f"expected an array but got: {jq_type_desc(v)}")

def _jq_recurse(v):
    yield v
    if isinstance(v,list):
        for x in v:yield from _jq_recurse(x)
    elif isinstance(v,dict):
        for k in sorted(v.keys(),key=lambda x:str(x)):yield from _jq_recurse(v[k])

def _jq_arith(op,a,b):
    if op=='+':
        if a is None:return b
        if b is None:return a
        if jq_is_number(a) and jq_is_number(b):
            x=jq_num_value(a); y=jq_num_value(b)
            if isinstance(x,int) and isinstance(y,int):return x+y
            return float(x)+float(y)
        if isinstance(a,str) and isinstance(b,str) and not isinstance(a,JsonNumber) and not isinstance(b,JsonNumber):return a+b
        if isinstance(a,list) and isinstance(b,list):return a+b
        if isinstance(a,dict) and isinstance(b,dict):
            out=dict(a); out.update(b); return out
        raise JqError(f"cannot add: {jq_type_desc(a)} and {jq_type_desc(b)}" if False else f"{jq_type_desc(a)} and {jq_type_desc(b)} cannot be added")
    if op=='-':
        if jq_is_number(a) and jq_is_number(b):
            x=jq_num_value(a);y=jq_num_value(b); return x-y if isinstance(x,int) and isinstance(y,int) else float(x)-float(y)
        if isinstance(a,list) and isinstance(b,list):
            return [x for x in a if not any(jq_equal(x,y) for y in b)]
        raise JqError(f"{jq_type_desc(a)} and {jq_type_desc(b)} cannot be subtracted")
    if op=='*':
        if jq_is_number(a) and jq_is_number(b):
            x=jq_num_value(a);y=jq_num_value(b); return x*y if isinstance(x,int) and isinstance(y,int) else float(x)*float(y)
        if isinstance(a,str) and jq_is_number(b):
            n=int(jq_num_value(b)); return a*n if n>0 else None
        if jq_is_number(a) and isinstance(b,str):
            n=int(jq_num_value(a)); return b*n if n>0 else None
        if isinstance(a,dict) and isinstance(b,dict):
            return _jq_deep_merge(a,b)
        raise JqError(f"{jq_type_desc(a)} and {jq_type_desc(b)} cannot be multiplied")
    if op=='/':
        ifjq = jq_is_number(a) and jq_is_number(b)
        if ifjq:
            x=float(jq_num_value(a));y=float(jq_num_value(b))
            if y==0:raise JqError(f"cannot divide number ({jq_preview(a)}) by: number ({jq_preview(b)})")
            return x/y
        if isinstance(a,str) and isinstance(b,str):
            return a.split(b) if b!="" else list(a)
        raise JqError(f"{jq_type_desc(a)} and {jq_type_desc(b)} cannot be divided")
    if op=='%':
        if jq_is_number(a) and jq_is_number(b):
            x=jq_num_value(a);y=jq_num_value(b)
            if int(y)==0:raise JqError("cannot calculate modulo")
            # jq % is remainder with sign of divisor? in jq, -5 % 3 = 1? In Go jq ints modulo truncates? We'll use Python floor? gojq: x - (x/y)*y with trunc division gives remainder sign dividend. Test reference later.
            xi=int(x); yi=int(y); return xi - int(xi/yi)*yi if False else xi % yi if yi>0 else -((-xi) % (-yi)) # placeholder python semantics for negative divisor different
        raise JqError(f"{jq_type_desc(a)} and {jq_type_desc(b)} cannot be modulo")
    raise JqError("bad operator")

def _jq_deep_merge(a,b):
    out=dict(a)
    for k,v in b.items():
        if k in out and isinstance(out[k],dict) and isinstance(v,dict):out[k]=_jq_deep_merge(out[k],v)
        else:out[k]=v
    return out

