# ---------------- mini gojq ----------------
class JqError(Exception):
    pass
class JqCompileError(JqError):
    pass

def jq_preview(v):
    # preview used in some error messages
    try:
        s=go_json_marshal_compact(v)
    except Exception:
        s=str(v)
    # Go jq preview truncates long representations approx - use 32 char limit for arrays/objects, string content 24 chars.
    if isinstance(v,str) and not isinstance(v,JsonNumber):
        if len(v)>24:
            s=_json_escape_string(v[:24]+" ...")
        return s
    if len(s)>48:
        return s[:45]+" ..."
    return s

def jq_type_name(v):
    if v is None: return "null"
    if isinstance(v,bool): return "boolean"
    if isinstance(v,(int,float,JsonNumber)): return "number"
    if isinstance(v,str): return "string"
    if isinstance(v,list): return "array"
    if isinstance(v,dict): return "object"
    return "value"

def jq_type_desc(v):
    if v is None:
        return "null"
    return f"{jq_type_name(v)} ({jq_preview(v)})"

def jq_truthy(v):
    return not (v is None or v is False)

def jq_num_value(v):
    """Return int/float numeric for a jq number, else None."""
    if isinstance(v,bool): return None
    if isinstance(v,JsonNumber):
        s=str(v)
        try:
            if re.fullmatch(r'-?(0|[1-9][0-9]*)', s):
                return int(s)
            return float(s)
        except Exception:
            return None
    if isinstance(v,(int,float)): return v
    return None

def jq_is_number(v):
    return jq_num_value(v) is not None

def jq_compare(a,b):
    # Return -1,0,1 using jq ordering
    def rank(v):
        if v is None: return 0
        if isinstance(v,bool): return 1 if v is False else 2
        if jq_is_number(v): return 3
        if isinstance(v,str): return 4
        if isinstance(v,list): return 5
        if isinstance(v,dict): return 6
        return 7
    ra,rb=rank(a),rank(b)
    if ra!=rb: return -1 if ra<rb else 1
    if a is None: return 0
    if isinstance(a,bool): return 0
    if jq_is_number(a):
        av=float(jq_num_value(a)); bv=float(jq_num_value(b))
        return (av>bv)-(av<bv)
    if isinstance(a,str):
        return (a>b)-(a<b)
    if isinstance(a,list):
        for x,y in zip(a,b):
            c=jq_compare(x,y)
            if c:return c
        return (len(a)>len(b))-(len(a)<len(b))
    if isinstance(a,dict):
        ak=sorted(a.keys(), key=lambda x: str(x)); bk=sorted(b.keys(), key=lambda x: str(x))
        for x,y in zip(ak,bk):
            if x!=y:return (str(x)>str(y))-(str(x)<str(y))
            c=jq_compare(a[x],b[y])
            if c:return c
        return (len(ak)>len(bk))-(len(ak)<len(bk))
    return 0

def jq_equal(a,b):
    return jq_compare(a,b)==0 if not (jq_is_number(a) and jq_is_number(b) and (math.isnan(float(jq_num_value(a))) or math.isnan(float(jq_num_value(b))))) else False

class JqParser:
    def __init__(self, text):
        self.s=text
        self.n=len(text)
        self.i=0
        self.defs={}
    def err(self,msg="unexpected token"):
        # Determine unexpected token like gojq? _compile error messages will be wrapped by caller.
        if self.i>=self.n:
            raise JqCompileError("unexpected EOF")
        raise JqCompileError(msg)
    def skip(self):
        while self.i<self.n:
            if self.s[self.i] in ' \t\r\n':
                self.i+=1; continue
            if self.s[self.i]=='#':
                while self.i<self.n and self.s[self.i]!='\n': self.i+=1
                continue
            break
    def starts(self, lit):
        self.skip()
        return self.s.startswith(lit, self.i)
    def consume(self, lit):
        self.skip()
        if self.s.startswith(lit,self.i):
            # For word literals ensure boundary if lit is alphabetic keyword
            self.i+=len(lit); return True
        return False
    def consume_word(self, word):
        self.skip()
        if self.s.startswith(word,self.i):
            j=self.i+len(word)
            if j>=self.n or not (self.s[j]=='_' or self.s[j].isalnum()):
                self.i=j; return True
        return False
    def peek_word(self, word):
        save=self.i
        r=self.consume_word(word)
        self.i=save
        return r
    def expect(self, lit):
        if not self.consume(lit):
            self.err(f"unexpected token {lit}")
    def parse(self):
        self.skip()
        # function definitions prelude (possibly several)
        while self.peek_word('def'):
            self.parse_def()
            self.skip()
        node=self.parse_pipe()
        self.skip()
        if self.i<self.n:
            self.err("unexpected token")
        return node
    def parse_def(self):
        self.consume_word('def')
        self.skip()
        name=self.parse_identifier()
        params=[]
        if self.consume('('):
            # parameters separated ; names maybe $var or identifiers
            while True:
                self.skip()
                if self.consume(')'):break
                if self.starts('$'):
                    params.append(self.parse_variable_name())
                else:
                    params.append(self.parse_identifier())
                if self.consume(';'):continue
                self.expect(')');break
        self.expect(':')
        body=self.parse_pipe()
        self.expect(';')
        self.defs[name]=(params,body)
    def parse_pipe(self):
        left=self.parse_comma()
        # "TERM as $x | ..."
        if self.peek_word('as'):
            self.consume_word('as')
            vars=[]
            while True:
                self.skip()
                if self.starts('$'):
                    vars.append(self.parse_variable_name())
                elif self.starts('{') or self.starts('['):
                    # destructuring pattern unsupported: consume balanced and ignore
                    self._consume_balanced()
                    vars.append(None)
                else:
                    self.err("expected variable")
                self.skip()
                if self.consume('?//'):
                    continue
                break
            self.expect('|')
            rest=self.parse_pipe()
            return ('bind', left, vars, rest)
        if self.consume('|'):
            right=self.parse_pipe()
            return ('pipe', left, right)
        return left
    def _consume_balanced(self):
        depth=0
        while self.i<self.n:
            c=self.s[self.i]; self.i+=1
            if c in '[{(':depth+=1
            elif c in ']})':
                depth-=1
                if depth==0:return
    def parse_comma(self):
        first=self.parse_alt()
        items=[first]
        while True:
            save=self.i
            if self.consume(','):
                items.append(self.parse_alt())
            else:break
        if len(items)==1:return first
        return ('comma', items)
    def parse_pipe_no_comma(self):
        left=self.parse_alt()
        if self.peek_word('as'):
            # Handles similarly but for object values rare
            self.consume_word('as'); vars=[]
            while True:
                self.skip(); vars.append(self.parse_variable_name() if self.starts('$') else None)
                if not self.consume('?//'):break
            self.expect('|'); rest=self.parse_pipe_no_comma(); return ('bind',left,vars,rest)
        if self.consume('|'):
            right=self.parse_pipe_no_comma()
            return ('pipe',left,right)
        return left
    def parse_alt(self):
        left=self.parse_or()
        while self.consume('//'):
            right=self.parse_or()
            left=('alt',left,right)
        return left
    def parse_or(self):
        left=self.parse_and()
        while self.consume_word('or'):
            right=self.parse_and(); left=('or',left,right)
        return left
    def parse_and(self):
        left=self.parse_compare()
        while self.consume_word('and'):
            right=self.parse_compare(); left=('and',left,right)
        return left
    def parse_compare(self):
        left=self.parse_add()
        while True:
            self.skip()
            op=None
            for cand in ('==','!=','<=','>=','<','>'):
                if self.s.startswith(cand,self.i):
                    op=cand; self.i+=len(cand);break
            if not op:break
            right=self.parse_add(); left=('cmp',op,left,right)
        return left
    def parse_add(self):
        left=self.parse_mul()
        while True:
            self.skip()
            if self.i<self.n and self.s[self.i] in '+-':
                # avoid interpreting '-' in number? binary op.
                op=self.s[self.i]; self.i+=1
                right=self.parse_mul(); left=('bin',op,left,right)
            else:break
        return left
    def parse_mul(self):
        left=self.parse_unary()
        while True:
            self.skip()
            if self.i<self.n and self.s[self.i] in '*/' and not self.s.startswith('//',self.i):
                op=self.s[self.i];self.i+=1; right=self.parse_unary(); left=('bin',op,left,right)
            elif self.i<self.n and self.s[self.i]=='%':
                self.i+=1; right=self.parse_unary(); left=('bin','%',left,right)
            else:break
        return left
    def parse_unary(self):
        self.skip()
        if self.i<self.n and self.s[self.i]=='-' and not (self.i+1<self.n and self.s[self.i+1].isdigit()):
            self.i+=1
            return ('neg', self.parse_unary())
        return self.parse_postfix()
    def parse_postfix(self):
        node=self.parse_base()
        while True:
            self.skip()
            if self.i<self.n and self.s[self.i]=='?':
                # ?// is handled in bind paths not postfix
                if self.s.startswith('?//',self.i): break
                self.i+=1; node=('optional',node); continue
            if self.i<self.n and self.s[self.i]=='[':
                # bracket suffix
                suffix=self.parse_bracket_suffix()
                node=('index_suffix',node,suffix); continue
            if self.i<self.n and self.s[self.i]=='.':
                # field/index suffix after a term such as $x.foo, (...) .foo maybe
                # Only consume if next is letter/_/" or [
                nxt=self.s[self.i+1] if self.i+1<self.n else ''
                if nxt=='[':
                    self.i+=1; suffix=self.parse_bracket_suffix(); node=('index_suffix',node,suffix); continue
                if nxt=='"' or nxt=='_' or nxt.isalpha():
                    self.i+=1
                    key=self.parse_field_name_after_dot()
                    node=('field_suffix',node,key); continue
                break
            break
        return node
    def parse_bracket_suffix(self):
        # current '['
        self.expect('[')
        self.skip()
        if self.consume(']'):
            return ('iter',)
        if self.consume(':'):
            # [ : end]
            self.skip()
            if self.consume(']'):
                return ('slice',None,None)
            end=self.parse_pipe_no_comma(); self.expect(']'); return ('slice',None,end)
        first=self.parse_pipe_no_comma()
        self.skip()
        if self.consume(':'):
            self.skip()
            if self.consume(']'):
                return ('slice',first,None)
            end=self.parse_pipe_no_comma(); self.expect(']'); return ('slice',first,end)
        self.expect(']')
        return ('index',first)
    def parse_field_name_after_dot(self):
        self.skip()
        if self.i<self.n and self.s[self.i]=='"':
            return self.parse_string_literal()[1]  # list of parts should be plain string
        m=re.match(r'[A-Za-z_][A-Za-z_0-9]*', self.s[self.i:])
        if not m:self.err("expected field")
        name=m.group(0); self.i+=len(name); return name
    def parse_identifier(self):
        self.skip()
        m=re.match(r'[A-Za-z_][A-Za-z_0-9]*', self.s[self.i:])
        if not m:self.err("expected identifier")
        name=m.group(0); self.i+=len(name)
        # namespace a::b
        while self.s.startswith('::',self.i):
            self.i+=2
            m2=re.match(r'[A-Za-z_][A-Za-z_0-9]*',self.s[self.i:])
            if not m2:self.err("expected identifier")
            name+='::'+m2.group(0); self.i+=len(m2.group(0))
        return name
    def parse_variable_name(self):
        self.skip()
        if not self.consume('$'):self.err("expected $")
        # $ENV, $__loc__, $$?
        if self.i<self.n and self.s[self.i]=='$':
            self.i+=1; return '$$'
        m=re.match(r'[A-Za-z_][A-Za-z_0-9]*',self.s[self.i:])
        if not m:self.err("expected var")
        name=m.group(0);self.i+=len(name); return name
    def parse_string_literal(self):
        # Returns ('string', parts) where parts are tuples ('str',text) or ('expr',node)
        self.skip()
        if self.i>=self.n or self.s[self.i]!='"':self.err("expected string")
        self.i+=1
        parts=[]; buf=[]
        def flush():
            if buf: parts.append(('str',''.join(buf))); buf.clear()
        while self.i<self.n:
            c=self.s[self.i]
            if c=='"':
                self.i+=1; flush(); return ('string',parts)
            if c=='\\':
                if self.i+1<self.n and self.s[self.i+1]=='(':
                    flush(); self.i+=2
                    node=self.parse_pipe(); self.expect(')'); parts.append(('expr',node)); continue
                if self.i+1>=self.n:self.err("unexpected EOF")
                e=self.s[self.i+1]; self.i+=2
                mp={ '"':'"','\\':'\\','/':'/','b':'\b','f':'\f','n':'\n','r':'\r','t':'\t'}
                if e in mp:buf.append(mp[e])
                elif e=='u':
                    if self.i+4>self.n:self.err("unexpected EOF")
                    txt=self.s[self.i:self.i+4]
                    try:buf.append(chr(int(txt,16)))
                    except:self.err("bad unicode")
                    self.i+=4
                else:
                    buf.append(e)
                continue
            buf.append(c); self.i+=1
        self.err("unexpected EOF")
    def parse_base(self):
        self.skip()
        if self.i>=self.n:self.err("unexpected EOF")
        # Recursive descent ..
        if self.s.startswith('..',self.i):
            # Ensure '..' not '...'
            self.i+=2; return ('recurse_descent',)
        c=self.s[self.i]
        if c=='.':
            # identity or field/index
            nxt=self.s[self.i+1] if self.i+1<self.n else ''
            if nxt=='"' or nxt=='_' or nxt.isalpha():
                self.i+=1; key=self.parse_field_name_after_dot(); return ('field',key)
            if nxt=='[':
                self.i+=1; suffix=self.parse_bracket_suffix(); return ('index_suffix',('identity',),suffix)
            self.i+=1; return ('identity',)
        if c=='"':
            return self.parse_string_literal()
        if c=='$':
            name=self.parse_variable_name(); return ('var',name)
        if c=='@':
            self.i+=1
            # @base64 etc can be followed by string? @format "..."? Treat as function
            ident=self.parse_identifier() if self.i<self.n and (self.s[self.i]=='_' or self.s[self.i].isalpha()) else ''
            return ('func','@'+ident, [])
        if c=='(':
            self.i+=1; node=self.parse_pipe(); self.expect(')'); return node
        if c=='[':
            self.i+=1; self.skip()
            if self.consume(']'): return ('array_construct',None)
            inner=self.parse_pipe(); self.expect(']'); return ('array_construct',inner)
        if c=='{':
            return self.parse_object_construct()
        if c.isdigit() or (c=='-' and self.i+1<self.n and self.s[self.i+1].isdigit()):
            return self.parse_number_literal()
        if c=='-' :
            # unary handled above but at base if -(
            self.i+=1; return ('neg',self.parse_postfix())
        if c=='_' or c.isalpha():
            # Keywords special
            if self.peek_word('if'):
                return self.parse_if()
            if self.peek_word('try'):
                self.consume_word('try')
                body=self.parse_postfix()
                catch=None
                if self.consume_word('catch'):
                    catch=self.parse_postfix()
                return ('try',body,catch)
            if self.peek_word('reduce'):
                return self.parse_reduce()
            if self.peek_word('foreach'):
                return self.parse_foreach()
            if self.peek_word('def'):
                # def only at start maybe nested - parse and then next pipe
                self.parse_def(); return self.parse_pipe()
            ident=self.parse_identifier()
            if ident in ('true','false'):return ('literal', ident=='true')
            if ident=='null':return ('literal',None)
            if ident=='__loc__':return ('func','__loc__',[])
            # function call args
            args=[]
            self.skip()
            if self.i<self.n and self.s[self.i]=='(':
                self.i+=1
                self.skip()
                if self.consume(')'):
                    args=[]
                else:
                    while True:
                        args.append(self.parse_pipe_no_comma())
                        self.skip()
                        if self.consume(';'):continue
                        self.expect(')');break
            return ('func',ident,args)
        self.err("unexpected token")
    def parse_number_literal(self):
        m=re.match(r'-?(0|[1-9][0-9]*)(\.[0-9]+)?([eE][+-]?[0-9]+)?', self.s[self.i:])
        if not m:self.err("bad number")
        txt=m.group(0); self.i+=len(txt)
        return ('literal', JsonNumber(txt))
    def parse_if(self):
        self.consume_word('if'); cond=self.parse_pipe_no_comma()
        if not self.consume_word('then'):self.err("expected then")
        then_node=self.parse_pipe_no_comma()
        elifs=[]
        else_node=None
        while self.consume_word('elif'):
            c=self.parse_pipe_no_comma(); 
            if not self.consume_word('then'):self.err("expected then")
            t=self.parse_pipe_no_comma(); elifs.append((c,t))
        if self.consume_word('else'):
            else_node=self.parse_pipe_no_comma()
        if not self.consume_word('end'):self.err("expected end")
        return ('if',cond,then_node,elifs,else_node)
    def parse_reduce(self):
        self.consume_word('reduce'); src=self.parse_postfix()
        if not self.consume_word('as'):self.err("expected as")
        var=self.parse_variable_name(); self.expect('('); init=self.parse_pipe_no_comma(); self.expect(';'); update=self.parse_pipe_no_comma(); self.expect(')')
        return ('reduce',src,var,init,update)
    def parse_foreach(self):
        self.consume_word('foreach'); src=self.parse_postfix()
        if not self.consume_word('as'):self.err("expected as")
        var=self.parse_variable_name(); self.expect('('); init=self.parse_pipe_no_comma(); self.expect(';'); update=self.parse_pipe_no_comma()
        extract=None
        if self.consume(';'): extract=self.parse_pipe_no_comma()
        self.expect(')')
        return ('foreach',src,var,init,update,extract)
    def parse_object_construct(self):
        self.expect('{')
        entries=[]
        self.skip()
        if self.consume('}'):return ('object_construct',entries)
        while True:
            self.skip()
            key_node=None; key_string=None; shorthand_field=None
            if self.i<self.n and self.s[self.i]=='(':
                self.i+=1; key_node=self.parse_pipe(); self.expect(')')
            elif self.i<self.n and self.s[self.i]=='"':
                sn=self.parse_string_literal(); key_node=sn
            elif self.i<self.n and self.s[self.i]=='.':
                # .field shorthand or key
                # consume .field
                self.i+=1; shorthand_field=self.parse_field_name_after_dot(); key_string=shorthand_field
            elif self.i<self.n and self.s[self.i]=='$':
                var=self.parse_variable_name(); key_string=var; shorthand_field=('var',var)
            else:
                # keyword / identifier
                ident=self.parse_identifier(); key_string=ident; shorthand_field=ident
            self.skip()
            if self.consume(':'):
                value=self.parse_pipe_no_comma()
            else:
                # shorthand
                if isinstance(shorthand_field,tuple):
                    value=shorthand_field
                elif shorthand_field is not None:
                    value=('field',shorthand_field)
                elif key_node is not None:
                    # {(key)} means get field by key expr; approximate as index
                    value=('index_suffix',('identity',),('index',key_node))
                else:
                    value=('identity',)
            entries.append((key_string,key_node,value))
            self.skip()
            if self.consume(','):
                continue
            self.expect('}');break
        return ('object_construct',entries)

# Evaluation
def jq_eval(node, value, env=None, defs=None):
    if env is None: env={}
    if defs is None: defs={}
    typ=node[0]
    if typ=='identity':
        yield value; return
    if typ=='literal':
        yield node[1]; return
    if typ=='string':
        parts=node[1]
        if not parts:
            yield ""; return
        # String interpolation yields one string per combination of expr outputs (usually first?). jq string interpolation uses each output? It constructs strings from each output of expression cartesian.
        # Implement recursive
        def rec(idx, cur):
            if idx>=len(parts):
                yield cur; return
            kind,part=parts[idx]
            if kind=='str':
                yield from rec(idx+1, cur+part)
            else:
                for out in jq_eval(part, value, env, defs):
                    yield from rec(idx+1, cur+_jq_to_string(out))
        yield from rec(0,""); return
    if typ=='var':
        name=node[1]
        if name=='ENV':
            yield dict(os.environ); return
        if name=='__progname':
            yield "jq"; return
        if name in env:
            yield env[name]; return
        raise JqError(f"variable not defined: ${name}/0" if False else f"${name} is not defined")
    if typ=='field':
        yield _jq_field(value,node[1]); return
    if typ=='field_suffix':
        for v in jq_eval(node[1],value,env,defs):
            yield _jq_field(v,node[2]); return
    if typ=='index_suffix':
        for v in jq_eval(node[1],value,env,defs):
            yield from _jq_apply_suffix(v,node[2],env,defs)
        return
    if typ=='recurse_descent':
        yield from _jq_recurse(value); return
    if typ=='optional':
        try:
            yield from jq_eval(node[1],value,env,defs)
        except JqError:
            return
        return
    if typ=='pipe':
        for mid in jq_eval(node[1],value,env,defs):
            yield from jq_eval(node[2],mid,env,defs)
        return
    if typ=='comma':
        for item in node[1]:
            yield from jq_eval(item,value,env,defs)
        return
    if typ=='bind':
        _,src,vars_,rest=node
        for out in jq_eval(src,value,env,defs):
            env2=dict(env)
            for vn in vars_:
                if vn: env2[vn]=out
            yield from jq_eval(rest,value,env2,defs)
        return
    if typ=='alt':
        produced=False
        try:
            for out in jq_eval(node[1],value,env,defs):
                if jq_truthy(out):
                    produced=True; yield out
        except JqError:
            pass
        if not produced:
            yield from jq_eval(node[2],value,env,defs)
        return
    if typ in ('and','or'):
        for a in jq_eval(node[1],value,env,defs):
            for b in jq_eval(node[2],value,env,defs):
                yield (jq_truthy(a) and jq_truthy(b)) if typ=='and' else (jq_truthy(a) or jq_truthy(b))
        return
    if typ=='cmp':
        _,op,left,right=node
        for a in jq_eval(left,value,env,defs):
            for b in jq_eval(right,value,env,defs):
                c=jq_compare(a,b)
                if op=='==':yield c==0
                elif op=='!=':yield c!=0
                elif op=='<':yield c<0
                elif op=='<=':yield c<=0
                elif op=='>':yield c>0
                elif op=='>=':yield c>=0
        return
    if typ=='bin':
        _,op,left,right=node
        for a in jq_eval(left,value,env,defs):
            for b in jq_eval(right,value,env,defs):
                yield _jq_arith(op,a,b)
        return
    if typ=='neg':
        for a in jq_eval(node[1],value,env,defs):
            n=jq_num_value(a)
            if n is None: raise JqError(f"cannot negate: {jq_type_desc(a)}")
            yield -n
        return
    if typ=='array_construct':
        inner=node[1]
        if inner is None:
            yield []; return
        yield list(jq_eval(inner,value,env,defs)); return
    if typ=='object_construct':
        entries=node[1]
        # Cartesian product of entries values/keys
        def rec(idx, cur):
            if idx>=len(entries):
                yield dict(cur); return
            key_str,key_node,val_node=entries[idx]
            # key outputs
            if key_node is not None:
                key_vals=list(jq_eval(key_node,value,env,defs))
            else:
                key_vals=[key_str]
            val_vals=list(jq_eval(val_node,value,env,defs))
            for kv in key_vals:
                ks=kv if isinstance(kv,str) and not isinstance(kv,JsonNumber) else _jq_to_string(kv) if not isinstance(kv,str) else kv
                if not isinstance(ks,str):
                    raise JqError(f"expected a string for object key but got: {jq_type_desc(kv)}")
                for vv in val_vals:
                    cur2=dict(cur); cur2[ks]=vv
                    yield from rec(idx+1,cur2)
        yield from rec(0,{}); return
    if typ=='if':
        _,cond,then_node,elifs,else_node=node
        for cv in jq_eval(cond,value,env,defs):
            if jq_truthy(cv):
                yield from jq_eval(then_node,value,env,defs)
            else:
                handled=False
                for (ec,et) in elifs:
                    for ev in jq_eval(ec,value,env,defs):
                        if jq_truthy(ev):
                            yield from jq_eval(et,value,env,defs); handled=True
                    if handled:break
                if not handled and else_node is not None:
                    yield from jq_eval(else_node,value,env,defs)
        return
    if typ=='try':
        _,body,catch=node
        try:
            yield from jq_eval(body,value,env,defs)
        except JqError as e:
            if catch is not None:
                yield from jq_eval(catch,str(e),env,defs)
            return
        return
    if typ=='reduce':
        _,src,var,init,update=node
        state=list(jq_eval(init,value,env,defs))
        if not state:return
        cur=state[0]
        for item in jq_eval(src,value,env,defs):
            env2=dict(env); env2[var]=item
            nxt=list(jq_eval(update,cur,env2,defs))
            if nxt:cur=nxt[0]
        yield cur; return
    if typ=='foreach':
        _,src,var,init,update,extract=node
        state=list(jq_eval(init,value,env,defs))
        if not state:return
        cur=state[0]
        for item in jq_eval(src,value,env,defs):
            env2=dict(env); env2[var]=item
            nxt=list(jq_eval(update,cur,env2,defs))
            if nxt:cur=nxt[0]
            if extract is not None:
                yield from jq_eval(extract,cur,env2,defs)
            else:
                yield cur
        return
    if typ=='func':
        yield from _jq_call(node[1],node[2],value,env,defs); return
    raise JqError(f"unsupported jq node {typ}")

def _jq_to_string(v):
    if isinstance(v,str) and not isinstance(v,JsonNumber): return v
    if v is None:return "null"
    return go_json_marshal_compact(v)

def _jq_field(v,key):
    if v is None:return None
    if isinstance(v,dict):return v.get(key,None)
    raise JqError(f"expected an object but got: {jq_type_desc(v)}")

def _jq_apply_suffix(v,suffix,env,defs):
    kind=suffix[0]
    if kind=='iter':
        if isinstance(v,list):
            yield from v; return
        if isinstance(v,dict):
            for k in sorted(v.keys(),key=lambda x:str(x)):yield v[k]
            return
        raise JqError(f"cannot iterate over: {jq_type_desc(v)}")
    if kind=='index':
        # index expr evaluated against original input? In jq, .[expr] evaluates expr against input v (same).
        idx_vals=list(jq_eval(suffix[1],v,env,defs))
        for idx in idx_vals:
            yield _jq_index(v,idx)
        return
    if kind=='slice':
        _,start_node,end_node=suffix
        starts=[None] if start_node is None else list(jq_eval(start_node,v,env,defs))
        ends=[None] if end_node is None else list(jq_eval(end_node,v,env,defs))
        for s in starts:
            for e in ends:
                yield _jq_slice(v,s,e)
        return

def _jq_index(v,idx):
    if v is None:return None
    if isinstance(idx,str) and not isinstance(idx,JsonNumber):
        return _jq_field(v,idx)
    n=jq_num_value(idx)
    if n is not None:
        if isinstance(n,float):
            # jq index must be integer? gojq trims?
            if not n.is_integer():
                raise JqError(f"array index must be an integer")
            n=int(n)
        if isinstance(v,list):
            i=n if n>=0 else len(v)+n
            if 0<=i<len(v):return v[i]
            return None
        if isinstance(v,str):
            chars=list(v)
            i=n if n>=0 else len(chars)+n
            if 0<=i<len(chars):return chars[i]
            return None
        raise JqError(f"expected an array but got: {jq_type_desc(v)}")
    raise JqError(f"expected a string or number for indexing")

def _jq_slice(v,s,e):
    if v is None:return None
    def toint(x):
        if x is None:return None
        n=jq_num_value(x)
        if n is None:raise JqError("slice index must be a number")
        return int(n)
    si=toint(s); ei=toint(e)
    if isinstance(v,list):
        return v[si:ei]
    if isinstance(v,str):
        chars=list(v); return ''.join(chars[si:ei])
    raise JqError(f"expected an array but got: {jq_type_desc(v)}")

def _jq_recurse(v):
    yield v
    if isinstance(v,list):
        for x in v:yield from _jq_recurse(x)
    elif isinstance(v,dict):
        for k in sorted(v.keys(),key=lambda x:str(x)):yield from _jq_recurse(v[k])

def _jq_arith(op,a,b):
    if op=='+':
        if a is None:return b
        if b is None:return a
        if jq_is_number(a) and jq_is_number(b):
            x=jq_num_value(a); y=jq_num_value(b)
            if isinstance(x,int) and isinstance(y,int):return x+y
            return float(x)+float(y)
        if isinstance(a,str) and isinstance(b,str) and not isinstance(a,JsonNumber) and not isinstance(b,JsonNumber):return a+b
        if isinstance(a,list) and isinstance(b,list):return a+b
        if isinstance(a,dict) and isinstance(b,dict):
            out=dict(a); out.update(b); return out
        raise JqError(f"cannot add: {jq_type_desc(a)} and {jq_type_desc(b)}" if False else f"{jq_type_desc(a)} and {jq_type_desc(b)} cannot be added")
    if op=='-':
        if jq_is_number(a) and jq_is_number(b):
