# Evaluation
def jq_eval(node, value, env=None, defs=None):
    if env is None: env={}
    if defs is None: defs={}
    typ=node[0]
    if typ=='identity':
        yield value; return
    if typ=='literal':
        yield node[1]; return
    if typ=='string':
        parts=node[1]
