    return out

def _jq_regex_funcs(name,args,value,env,defs):
    if not args:raise JqError(f"{name} not defined")
    pat=_jq_first(args[0],value,env,defs)
    flags=""
    if len(args)>=2 and name in ('test','match','capture','splits','sub','gsub'):
        # flags may be second arg for test/match/capture/splits, but sub second is replacement
        pass
    if not isinstance(value,str) or not isinstance(pat,str):
        raise JqError(f"{name} cannot be applied")
    # regex flags for these functions: second arg may be flags except sub/gsub where args are (re; newstr; flags)
    re_flags=0
    flag_str=""
    if name in ('test','match','capture') and len(args)>=2:
        flag_str=_jq_first(args[1],value,env,defs) or ""
    if name=='splits' and len(args)>=2:
        flag_str=_jq_first(args[1],value,env,defs) or ""
    if name in ('sub','gsub') and len(args)>=3:
        flag_str=_jq_first(args[2],value,env,defs) or ""
    if isinstance(flag_str,str):
        if 'i' in flag_str:re_flags|=re.IGNORECASE
        if 'm' in flag_str:re_flags|=re.MULTILINE
        if 's' in flag_str:re_flags|=re.DOTALL
        if 'x' in flag_str:re_flags|=re.VERBOSE
    try:
        regex=re.compile(pat,re_flags)
    except Exception as e:
        raise JqError(str(e))
    global_flag = isinstance(flag_str,str) and 'g' in flag_str
    if name=='test':
        yield bool(regex.search(value));return
    if name=='match':
        matches=regex.finditer(value) if global_flag else ([regex.search(value)] if regex.search(value) else [])
        for m in matches:
            if m is None:continue
            out={"offset":len(value[:m.start()]),"length":len(value[m.start():m.end()]),"string":m.group(0),"captures":[]}
            for gi in range(1,(m.re.groups or 0)+1):
                g=m.group(gi)
                if g is None:out["captures"].append({"offset":-1,"length":0,"string":None,"name":m.re.groupindex.get(str(gi)) if False else _group_name(regex,gi)})
                else:out["captures"].append({"offset":len(value[:m.start(gi)]),"length":len(g),"string":g,"name":_group_name(regex,gi)})
            yield out
        return
    if name=='capture':
        m=regex.search(value)
        if not m:return
        out={}
        # named groups
        if regex.groupindex:
            for gn,gi in regex.groupindex.items():out[gn]=m.group(gi)
