            vals=list(jq_eval(repl_node,m.group(0),env,defs))
            return _jq_to_string(vals[0]) if vals else ""
        yield regex.sub(repl_func,value,count=count);return

def _group_name(regex,idx):
    for n,i in regex.groupindex.items():
        if i==idx:return n
    return None

def _jq_splits(regex,value):
    # splits yields substrings
    yield from regex.split(value)

def run_jq(query,value):
    """Compile and run query against one value, return list outputs. Raise JqError with messages (caller formats trailing query spec)."""
    if query=="" or query is None:
        return [value]
    parser=JqParser(query)
    try:
        node=parser.parse()
    except JqCompileError:
        raise
    defs=parser.defs
    try:
        return list(jq_eval(node,value,{},defs))
    except JqError:
        raise

def jq_compile_error_msg(query):
    # Used when parser errors; gojq pretty prints query maybe differently, use original query text in parentheses
    return query

