def _jq_first(node, value, env, defs):
    vals=list(jq_eval(node,value,env,defs))
    return vals[0] if vals else None

def _jq_call(name,args,value,env,defs):
    # User defined defs
    if defs and name in defs:
        params,body=defs[name]
        env2=dict(env)
        for pname, anode in zip(params,args):
            # Function params in jq are filters, not values, closure approximation: evaluate as a value at call point if param referenced as $pname; if referenced as pname filter in body, our func dispatch doesn't handle. Store node in a special map by binding a variable to first output if body uses $.
            # Simplify: evaluate arg against call input and store first.
            vals=list(jq_eval(anode,value,env,defs))
            env2[pname]=vals[0] if vals else None
