        yield value; return
    if name=='stderr':
        yield value; return
    if name=='__loc__':
        yield {"file":"<top-level>","line":1}; return
    if name=='env' or name=='$ENV':
        yield dict(os.environ); return
    if name=='length':
        if value is None:yield 0
        elif jq_is_number(value):yield abs(jq_num_value(value))
        elif isinstance(value,(str,list,dict)):yield len(value) if not isinstance(value,str) else len(list(value))
        else:raise JqError(f"{jq_type_desc(value)} has no length")
