    if name=='values':
        if value is not None:yield value
        return
    if name=='scalars' or name=='booleans' or name=='numbers' or name=='strings' or name=='arrays' or name=='objects' or name=='iterables' or name=='nulls':
        ok=False
        if name=='scalars':ok=not isinstance(value,(list,dict))
        elif name=='booleans':ok=isinstance(value,bool)
        elif name=='numbers':ok=jq_is_number(value)
        elif name=='strings':ok=isinstance(value,str) and not isinstance(value,JsonNumber)
        elif name=='arrays':ok=isinstance(value,list)
        elif name=='objects':ok=isinstance(value,dict)
        elif name=='iterables':ok=isinstance(value,(list,dict))
        elif name=='nulls':ok=value is None
        if ok:yield value
        return
    if name=='type':
