def _freeze(v):
    if isinstance(v,dict):return tuple(sorted(((k,_freeze(x)) for k,x in v.items()),key=lambda t:str(t[0])))
    if isinstance(v,list):return tuple(_freeze(x) for x in v)
    if isinstance(v,JsonNumber):return ('num',float(v))
    return v

def _jq_sort_key(v):
    # For Python sorted, need comparable key matching jq order.
    # Return nested tuple representation.
    if v is None:return (0,)
    if isinstance(v,bool):return (1 if not v else 2,)
    if jq_is_number(v):return (3,float(jq_num_value(v)))
    if isinstance(v,str):return (4,v)
    if isinstance(v,list):return (5,tuple(_jq_sort_key(x) for x in v))
    if isinstance(v,dict):
        return (6,tuple(sorted(((str(k),_jq_sort_key(x)) for k,x in v.items()),key=lambda t:t[0])))
    return (7,str(v))

def _jq_contains(a,b):
    if isinstance(a,str) and isinstance(b,str):return b in a
    if isinstance(a,list) and isinstance(b,list):return all(any(jq_equal(x,y) for y in a) or _jq_contains_any(a,x) for x in b) if False else all(any(_jq_contains(elem,x) for elem in a) for x in b)
    if isinstance(a,dict) and isinstance(b,dict):return all(k in a and _jq_contains(a[k],v) for k,v in b.items())
    return jq_equal(a,b)
def _jq_contains_any(arr, needle):
    return any(_jq_contains(x,needle) for x in arr)

def _jq_format(fmt,value):
    if fmt=='text':return _jq_to_string(value) if not isinstance(value,str) else value
    if fmt=='json':return go_json_marshal_compact(value)
    if fmt in ('html','uri','csv','tsv','sh','base64','base64d'):
        s=value if isinstance(value,str) else _jq_to_string(value)
        if fmt=='base64':return base64.b64encode(s.encode()).decode()
        if fmt=='base64d':
            try:return base64.b64decode(s.encode()).decode()
            except Exception as e:raise JqError(str(e))
        if fmt=='html':return s.replace('&','&amp;').replace('<','&lt;').replace('>','&gt;').replace('"','&quot;').replace("'","&#39;")
        if fmt=='uri':
            from urllib.parse import quote
            return quote(s,safe='')
        if fmt=='csv':return '"'+s.replace('"','""')+'"' if isinstance(value,str) else s
        if fmt=='tsv':return s.replace('\\','\\\\').replace('\n','\\n').replace('\r','\\r').replace('\t','\\t')
        if fmt=='sh':return "'" + s.replace("'","'\\''") + "'"
    return _jq_to_string(value)

def _jq_paths(value,scalar_only=False,prefix=None):
    if prefix is None:prefix=[]
    if isinstance(value,list):
        if not scalar_only and prefix:yield prefix
        for i,x in enumerate(value):yield from _jq_paths(x,scalar_only,prefix+[i])
    elif isinstance(value,dict):
        if not scalar_only and prefix:yield prefix
        for k in value:yield from _jq_paths(value[k],scalar_only,prefix+[k])
    else:
        if prefix:yield prefix

def _jq_getpath(v,path):
    if not isinstance(path,list):raise JqError("path must be array")
    cur=v
    for p in path:
        if isinstance(p,str) and not isinstance(p,JsonNumber):cur=_jq_field(cur,p)
        else:cur=_jq_index(cur,p)
    return cur

def _jq_setpath(v,path,newv):
    if not path:return newv
    import copy
    result=copy.deepcopy(v)
    cur=result
    for i,p in enumerate(path):
        last=i==len(path)-1
        if isinstance(p,str) and not isinstance(p,JsonNumber):
            if not isinstance(cur,dict):raise JqError("cannot setpath")
            if last:cur[p]=newv
            else:
                if p not in cur or not isinstance(cur[p],(dict,list)):cur[p]={} if isinstance(path[i+1],str) else []
                cur=cur[p]
        else:
            idx=int(jq_num_value(p))
            if not isinstance(cur,list):raise JqError("cannot setpath")
            if idx<0:idx+=len(cur)
            while len(cur)<=idx:cur.append(None)
            if last:cur[idx]=newv
            else:
                if not isinstance(cur[idx],(dict,list)):cur[idx]={} if isinstance(path[i+1],str) else []
                cur=cur[idx]
    return result

def _jq_delpath(v,path):
    import copy
    if not path:return v
    result=copy.deepcopy(v); cur=result
    for i,p in enumerate(path):
        last=i==len(path)-1
        if isinstance(p,str) and not isinstance(p,JsonNumber):
            if not isinstance(cur,dict):return result
            if last:cur.pop(p,None)
            else:cur=cur.get(p)
        else:
            idx=int(jq_num_value(p) or 0)
            if not isinstance(cur,list):return result
            if last:
                if 0<=idx<len(cur):cur.pop(idx)
            else:cur=cur[idx] if 0<=idx<len(cur) else None
    return result

def _jq_path_from_node(node,value,env,defs):
    # simple path extraction for del(.a.b[0])
    path=[]
    n=node
    chain=[]
    while True:
        if n[0]=='identity':break
        if n[0]=='field':chain.append(n[1]);break
        if n[0]=='field_suffix':chain.append(n[2]);n=n[1];continue
        if n[0]=='index_suffix':
            suf=n[2]
            if suf[0]=='index':
                vals=list(jq_eval(suf[1],value,env,defs));chain.append(vals[0] if vals else None)
            n=n[1];continue
        break
    return list(reversed(chain))

def _jq_flatten(arr,depth):
    out=[]
    for x in arr:
        if isinstance(x,list) and (depth is None or depth>0):
            out.extend(_jq_flatten(x, None if depth is None else depth-1))
        else:out.append(x)
    return out

