# ---------------- readers ----------------
def O(opts, name):
    return getattr(opts, name)

class ImportPreError(Exception):
    pass

class ReaderInfo:
    def __init__(self):
        self.names=[]
        self.types=[]
        self.preread_rows=[]
        self.remaining_rows=[]
        self.format_kind="CSV"
        self.format_display="CSV"
