def _filepath_ext(name):
    # Go filepath.Ext: suffix beginning at final dot in final element
    final=name.rsplit('/',1)[-1]
    i=final.rfind('.')
    if i<0: return ""
    return final[i:]

INPUT_GUESS_MAP={
    'csv':'CSV','tsv':'TSV','psv':'PSV','ltsv':'LTSV','json':'JSON','jsonl':'JSON','yaml':'YAML','yml':'YAML','tbln':'TBLN','text':'TEXT','width':'WIDTH'
}
FORMAT_DISPLAY={'CSV':'CSV','TSV':'TSV','PSV':'PSV','LTSV':'LTSV','JSON':'JSON','YAML':'YAML','TBLN':'TBLN','TEXT':'Unknown','WIDTH':'WIDTH'}

def guess_input_format(file_name, log_debug=True):
    cur=file_name
    while True:
        ext=_filepath_ext(cur)
        if ext=="":
            root=cur
            if len(root)>=2 and root[0] in ('"',"'",'`') and root[-1]==root[0]:
                root=root[:-1]
            if log_debug:
                debug_log(f"Set in CSV because the extension is unknown: [{root}]")
                debug_log(f"Guess file type as CSV: [{file_name}]")
            return 'CSV'
        key=ext[1:].lower()
        if key in INPUT_GUESS_MAP:
            fmt=INPUT_GUESS_MAP[key]
            if log_debug:
                debug_log(f"Guess file type as {FORMAT_DISPLAY[fmt]}: [{file_name}]")
            return fmt
        cur=cur[:-len(ext)]

def select_input_format(opts, file_name, log_debug=True):
    # explicit precedence
    if opts.icsv: return 'CSV', True
    if opts.iltsv: return 'LTSV', True
    if opts.ijson: return 'JSON', True
    if opts.iyaml: return 'YAML', True
    if opts.itbln: return 'TBLN', True
    if opts.iwidth: return 'WIDTH', True
    if opts.itext: return 'TEXT', True
    return guess_input_format(file_name, log_debug=log_debug), False

def split_go_lines(text):
    if text=="":
        return []
    parts=text.split('\n')
    if text.endswith('\n'):
        parts=parts[:-1]
    return [p[:-1] if p.endswith('\r') else p for p in parts]

def _go_slice_str(vals):
    # Go %v for a slice of strings/interface: [a b], nil as <nil>
    def one(v):
        if v is None:return "<nil>"
        return go_value_string(v)
    return '['+' '.join(one(v) for v in vals)+']'

def _effective_preread(opts, format_kind, for_import=True):
    ilr=getattr(opts,'ilr'); ir=getattr(opts,'ir'); skip=getattr(opts,'is')
    if not for_import:
        return ir
    if ilr and ilr>0:
        if format_kind in ('TEXT',):
            return ilr
        return ilr + (skip if skip and skip>0 else 0)
    return ir

def _apply_limit_count(opts, format_kind):
    ilr=getattr(opts,'ilr'); skip=getattr(opts,'is')
    if ilr and ilr>0:
        if format_kind in ('TEXT',):
            return ilr
        return ilr + (skip if skip and skip>0 else 0)
    return None

def _adjust_row(row, n, missing=None):
    if len(row)>n:
        return list(row[:n])
    if len(row)<n:
        return list(row)+[missing]*(n-len(row))
    return list(row)

def _csv_reader(opts, data_text, format_kind, explicit, for_import=True):
    info=ReaderInfo(); info.format_kind=format_kind; info.format_display=FORMAT_DISPLAY[format_kind]
    skip=getattr(opts,'is')
    # delimiter
    if format_kind=='TSV':
        delim='\t'
    elif format_kind=='PSV':
        delim='|'
    else:
        try:
            delim=get_separator(opts.id)
        except SeparatorError as e:
            raise ImportPreError(f"can not get separator: {e}")
    if delim in ('\x00','"', '\r','\n','\ufffd') or (len(delim)==1 and 0xD800 <= ord(delim) <= 0xDFFF):
        raise ImportPreError("csv: invalid field or comment delimiter")
    records=parse_csv_records(data_text, delim)
    # skip
    total_records=len(records)
    idx=0
    if skip and skip>0:
        for i in range(skip):
            if idx<total_records:
                debug_log(f"Skip row:{_go_slice_str(records[idx])}")
                idx+=1
            else:
                error_log("ERROR: skip error EOF")
                break
    remaining=records[idx:]
    if opts.ih:
        if not remaining:
            info.csv_no_rows=True
            # no EOF debug in ih case (observed)
            return info
        header=remaining[0]
        names=[]
        for i,h in enumerate(header):
            names.append(h if h!="" else f"c{i+1}")
        info.names=names
        info.types=['text']*len(names)
        data_records=remaining[1:]
        eff=_effective_preread(opts, format_kind, for_import)
        limit=_apply_limit_count(opts, format_kind) if for_import else None
        included=data_records[:limit] if (for_import and limit is not None) else data_records
        rows=[_adjust_row(r,len(names),None) for r in included]
        if eff and eff>0:
            info.preread_rows=rows[:eff]
            info.remaining_rows=rows[eff:] if limit is None else []
            if limit is not None:
                info.preread_rows=rows
                info.remaining_rows=[]
        else:
            info.preread_rows=[]
            info.remaining_rows=rows if limit is None else rows
            # If limit applies, rows are inserted as bulk in debug as one group; importer will treat preread empty + remaining. For insert debug grouping, importer logs preread insert then remaining insert. With eff<=0 and ih, debug showed one insert for all rows (bulk phase). That's remaining.
            if limit is not None:
                info.preread_rows=[]; info.remaining_rows=rows
        return info
    # no header
    eff=_effective_preread(opts, format_kind, for_import)
    if for_import and (eff is None or eff<=0):
        info.csv_no_rows=True
        return info
    if not for_import and (eff is None or eff<=0):
        # Analyze with ir<=0 for CSV? treat as no rows sample/names? Return names [] maybe importer of analyze handles.
        info.csv_no_rows=True
        return info
    preread=remaining[:eff] if eff and eff>0 else []
    if not preread:
        info.eof_debug=True
        info.csv_no_rows=True
        return info
    maxcols=max(len(r) for r in preread)
    info.names=[f"c{i+1}" for i in range(maxcols)]
    info.types=['text']*maxcols
    limit=_apply_limit_count(opts, format_kind) if for_import else None
    included_records=remaining[:limit] if limit is not None else remaining
    rows=[_adjust_row(r,maxcols,None) for r in included_records]
    if limit is not None:
        info.preread_rows=rows; info.remaining_rows=[]
    else:
        # preread rows need adjustment too (already rows[:eff])
        info.preread_rows=rows[:eff]; info.remaining_rows=rows[eff:]
    return info

def _ltsv_reader(opts, data_text, for_import=True):
    info=ReaderInfo(); info.format_kind='LTSV'; info.format_display='LTSV'
    lines=split_go_lines(data_text)
    # Build raw record dicts with possible error per record index (after ignoring blank)
    raw_records=[]  # dict order, or error marker string
    record_errors={} # index -> msg
    for line in lines:
        if line=="":
            continue
        fields=line.split('\t')
        rec={}
        err=False
        for f in fields:
            if f=="":continue
            if ':' not in f:
                err=True;break
            k,v=f.split(':',1); rec[k]=v
        if err:
            record_errors[len(raw_records)]="invalid column"
            raw_records.append(None)
            break  # stream stops at error; records beyond not processed
        raw_records.append(rec)
    skip=getattr(opts,'is')
    idx=0
    # Skip is performed via reader's skip function reading records (including possibly error records?). Implement records-based skip.
    if skip and skip>0:
        for i in range(skip):
            if idx < len(raw_records):
                # Debug format observed [<nil>] for LTSV
                debug_log("Skip row:[<nil>]")
                idx+=1
            else:
                error_log("ERROR: skip error EOF")
                break
    records=raw_records[idx:]
    # Adjust error indices relative to after skip
    rel_errors={k-idx:v for k,v in record_errors.items() if k>=idx}
    eff=_effective_preread(opts,'LTSV',for_import)
    if not records:
        info.eof_debug=True
        info.names=[]; info.types=[]
        return info
    # If first errors within preread range: pre error
    # names from records up to eff, skipping error records (but error triggers)
    preread_count = eff if eff and eff>0 else 0
    # If eff<=0, names [] will cause invalid names in importer (matches ir0)
    names=[]
    for ridx,rec in enumerate(records[:preread_count] if preread_count>0 else []):
        if ridx in rel_errors:
            raise ImportPreError(rel_errors[ridx])
        for k in rec.keys():
            if k not in names:names.append(k)
    info.names=names; info.types=['text']*len(names)
    limit=_apply_limit_count(opts,'LTSV') if for_import else None
    included_count = limit if limit is not None else len(records)
    rows=[]
    bulk_err=None
    for ridx,rec in enumerate(records[:included_count]):
        if ridx in rel_errors:
            if ridx < preread_count:
                raise ImportPreError(rel_errors[ridx])
            bulk_err=rel_errors[ridx]
            break
        rows.append([rec.get(name,"") if rec is not None else "" for name in names])
    # Errors after included_count are ignored when limited.
    if limit is not None:
        info.preread_rows=rows; info.remaining_rows=[]
    else:
        info.preread_rows=rows[:preread_count]; info.remaining_rows=rows[preread_count:]
    info.bulk_error=bulk_err
    return info

def _json_value_to_db(v):
    if v is None:return None
    if isinstance(v,bool):return "true" if v else "false"
    if isinstance(v,JsonNumber):return str(v)
    if isinstance(v,int):return str(v)
    if isinstance(v,float):return go_float_g(v)
    if isinstance(v,str):return v
    if isinstance(v,(list,dict)):return go_json_marshal_compact(v)
    return str(v)

def _yaml_value_to_db(v):
    if v is None:return None
    if isinstance(v,bool):return "true" if v else "false"
    if isinstance(v,int):return str(v)
    if isinstance(v,float):return go_float_g(v)
    if isinstance(v,str):return v
    if isinstance(v,(list,dict)):return _yaml_nested_string(v)
    return str(v)

def _generic_names_and_rows(values, converter):
    names=[]
    for val in values:
        if isinstance(val,dict):
            for k in val.keys():
                ks=_scalar_to_string_for_db(k) if not isinstance(k,str) else k
                if ks is None:ks=""
                if ks not in names:names.append(ks)
        else:
            if 'c1' not in names:names.append('c1')
    rows=[]
    for val in values:
        if isinstance(val,dict):
            # Need lookup by stringified key
            keymap={}
            for k,v in val.items():
                ks=_scalar_to_string_for_db(k) if not isinstance(k,str) else k
                if ks is None:ks=""
                keymap[ks]=v
            rows.append([converter(keymap[name]) if name in keymap else None for name in names])
        else:
            row=[]
            for name in names:
                row.append(converter(val) if name=='c1' else None)
            rows.append(row)
    return names,rows

def _format_jq_error(e, query, compile_err=False):
    msg=str(e)
    # gojq runtime errors end with a space in trdsql wrapper as observed (error struct prints query + token)
    if compile_err:
        return f"{msg} gojq:({query})"
    return f"{msg} gojq:({query}) "

def _json_reader(opts, data_bytes, jq_expr, for_import=True):
    info=ReaderInfo(); info.format_kind='JSON'; info.format_display='JSON'
    parser=JSONParser(data_bytes)
    # Decode first value
    parser.skip_ws()
    if parser.eof():
        info.eof_debug=True; info.names=[]; info.types=[]; return info
    try:
        first=parser.parse_value()
    except JSONEOF:
        info.eof_debug=True; info.names=[]; info.types=[]; return info
    except GoJSONError as e:
        raise ImportPreError(f"invalid JSON: {e}")
    # Determine if more non-ws remains BEFORE interpreting jq outputs (based on raw stream)
    save_pos=parser.pos
    parser.skip_ws()
    has_more = not parser.eof()
    parser.pos=save_pos
    # Apply jq to first or set outputs
    def apply_jq(val):
        if not jq_expr:
            return [val]
        try:
            pp=JqParser(jq_expr); node=pp.parse(); defs=pp.defs
            return list(jq_eval(node,val,{},defs))
        except JqCompileError as e:
            # compile errors have no trailing space in wrapper
            raise ImportPreError(_format_jq_error(e,jq_expr,compile_err=True))
        except JqError as e:
            raise
    jq_parser=None; jq_node=None; jq_defs={}
    if jq_expr:
        try:
            jq_parser=JqParser(jq_expr); jq_node=jq_parser.parse(); jq_defs=jq_parser.defs
        except JqCompileError as e:
            raise ImportPreError(_format_jq_error(e,jq_expr,compile_err=True))
    def apply_jq2(val):
        if not jq_expr:return [val]
        return list(jq_eval(jq_node,val,{},jq_defs))
    try:
        outputs_first=apply_jq2(first)
    except JqError as e:
        raise ImportPreError(_format_jq_error(e,jq_expr,compile_err=False))
    # Bulk array mode
    if len(outputs_first)==1 and isinstance(outputs_first[0],list) and not has_more:
        values=list(outputs_first[0])
        names,rows=_generic_names_and_rows(values,_json_value_to_db)
        info.names=names; info.types=['text']*len(names); info.preread_rows=rows; info.remaining_rows=[]
        return info
    # Stream mode: generate row values sequentially until EOF/error
    row_values=list(outputs_first)
    error_after=None
    bulk_error_msg=None
    pre_error_msg=None
    # We need to know target preread to classify errors, but generation continues beyond.
    eff=_effective_preread(opts,'JSON',for_import)
    limit=_apply_limit_count(opts,'JSON') if for_import else None
    # Continue parsing subsequent values, but if limit set we can stop generating once we have limit row values and no need to parse further for included rows.
    # For names when no limit, only first eff rows matter but errors after eff become bulk.
    while True:
        parser.skip_ws()
        if parser.eof():
            break
        # if limit and we already have enough rows, stop before parsing next (original limited reader stops)
        if limit is not None and len(row_values)>=limit:
            break
        try:
            nxt=parser.parse_value()
            outs=apply_jq2(nxt)
        except GoJSONError as e:
            error_after=len(row_values)
            bulk_error_msg=str(e)
            pre_error_msg=f"invalid JSON: {e}"
            break
        except JqError as e:
            error_after=len(row_values)
            bulk_error_msg=_format_jq_error(e,jq_expr,compile_err=False)
            pre_error_msg=bulk_error_msg
            break
        row_values.extend(outs)
    # Names based on preread target
    preread_target = eff if eff and eff>0 else 0
    # If error occurred while trying to fill preread (error_after < preread_target) and error_after !=0? But if error occurs before any more values needed? Original reader Names may attempt exactly preread_target reads; if stream ends naturally before target, it's fine, but a parse error encountered as it tries to read next counts.
    if error_after is not None and error_after < preread_target:
        # BUT if the target could not be met because only parse error stands in the way, is it pre-error? If error_after ==0 not possible (first handled).
        raise ImportPreError(pre_error_msg)
    if limit is not None:
        row_values_included=row_values[:limit]
    else:
        row_values_included=row_values
    names, all_rows=_generic_names_and_rows(row_values_included[:preread_target] if preread_target>0 else [], _json_value_to_db)
    # Recompute rows for all included with names (rows outside preread should be aligned to names, not their own keys)
    # Build conversion manually for all included using names determined.
    rows=[]
    for val in row_values_included:
        if isinstance(val,dict):
            km={}
            for k,v in val.items():
                ks=_scalar_to_string_for_db(k) if not isinstance(k,str) else k
                if ks is None:ks=""
                km[ks]=v
            rows.append([_json_value_to_db(km[name]) if name in km else None for name in names])
        else:
            rows.append([_json_value_to_db(val) if name=='c1' else None for name in names])
    info.names=names; info.types=['text']*len(names)
    if limit is not None:
        info.preread_rows=rows; info.remaining_rows=[]
    else:
        info.preread_rows=rows[:preread_target]; info.remaining_rows=rows[preread_target:]
    if error_after is not None and error_after>=preread_target:
        # If limited and error_after >= limit, original wouldn't parse it (we break before) so no error set.
        info.bulk_error=bulk_error_msg
    return info

def _yaml_reader(opts, data_bytes, for_import=True):
    info=ReaderInfo(); info.format_kind='YAML'; info.format_display='YAML'
    text=data_bytes.decode('utf-8','surrogateescape') if isinstance(data_bytes,(bytes,bytearray)) else data_bytes
    if text.strip()=="":
        info.eof_debug=True; info.names=[]; info.types=[]; return info
    try:
        docs=parse_yaml_documents(text)
    except YAMLError as e:
        raise ImportPreError(f"invalid YAML: {e}")
    if not docs:
        info.eof_debug=True; info.names=[]; info.types=[]; return info
    values=[]
    if len(docs)==1:
        doc=docs[0]
        if isinstance(doc,list):values=list(doc)
        else:values=[doc]
    else:
        # Approximation: flatten list docs, others as rows
        for doc in docs:
            if isinstance(doc,list):values.extend(doc)
            else:values.append(doc)
    names,rows=_generic_names_and_rows(values,_yaml_value_to_db)
    info.names=names; info.types=['text']*len(names); info.preread_rows=rows; info.remaining_rows=[]
    return info

def _parse_tbln_row(s):
    if s=='| |':
        return []
    if not (s.startswith('| ') and s.endswith(' |')):
        return None
    inner=s[2:-2] if len(s)>=4 else ''
    cells=inner.split(' | ')
    return [None if c=="" else c.replace('||','|') for c in cells]

def _tbln_reader(opts, data_text, for_import=True):
    info=ReaderInfo(); info.format_kind='TBLN'; info.format_display='TBLN'
    lines=split_go_lines(data_text)
    names_def=None; types_def=None
    names=None; types=None; expected=None
    row_events=[]  # list of either list of cells (maybe zero len) or error string markers ('ERR',msg)
    def validate_defs():
        if names_def is not None and types_def is not None and len(names_def)!=len(types_def):
            raise ImportPreError("number of columns is different")
    first_data_seen=False
    for raw_line in lines:
        line=raw_line
        if line.startswith('#'):
            continue
        if line.startswith('; '):
            body=line[2:]
            # key: value
            colon=body.find(':')
            if colon<0:
                row_events.append(('ERR',f"unsupported line ({line})")); break
            key=body[:colon].strip(); val=body[colon+1:].lstrip(' ')
            # Definition value for name/type must be row; if val doesn't parse, original might treat definition line as unsupported? It likely parses val as row only for known keys and on failure returns unsupported line for val or line.
            if key in ('name','type'):
                parsed=_parse_tbln_row(val)
                if parsed is None:
                    row_events.append(('ERR',f"unsupported line ({val})")); break
                vals=[c if c is not None else "" for c in parsed]
                if key=='name':
                    if not first_data_seen: names_def=vals
                else:
                    if not first_data_seen: types_def=vals
                try:
                    validate_defs()
                except ImportPreError:
                    raise
            continue
        if line=="":
            row_events.append([]); continue
        if line.startswith('|'):
            parsed=_parse_tbln_row(line)
            if parsed is None:
                row_events.append(('ERR',f"unsupported line ({line})")); break
            # At first data row, decide names/types/expected
            if not first_data_seen:
                first_data_seen=True
                validate_defs()
                if names_def is not None:
                    names=list(names_def)
                elif types_def is not None:
                    names=[f"c{i+1}" for i in range(len(types_def))]
                else:
                    names=[f"c{i+1}" for i in range(len(parsed))]
                if types_def is not None:
                    types=list(types_def)
                else:
                    types=['text']*len(names)
                expected=len(names)
            if len(parsed)==0:
                row_events.append([]); continue
            if expected is not None and len(parsed)!=expected:
                msg=f"invalid column num ({expected}!={len(parsed)}) {_go_slice_str(parsed)}"
                row_events.append(('ERR',msg)); break
            row_events.append(parsed); continue
        # unsupported
        row_events.append(('ERR',f"unsupported line ({line})")); break
    if names is None:
        # no data rows
        validate_defs()
        if names_def is not None:
            names=list(names_def); types=list(types_def) if types_def is not None else ['text']*len(names)
        elif types_def is not None:
            types=list(types_def); names=[f"c{i+1}" for i in range(len(types))]
        else:
            names=[]; types=[]
        info.eof_debug=True
    info.names=names or []; info.types=types or []
    # If an error event is first row error and occurs before any data / in preread, it'll be classified below.
    # Zero rows should be kept in preread for expected-args behavior, and filtered in remaining.
    # Build sequences: data_rows are events that are list (incl zero) until an ERR segment.
    # But names could be [] - importer invalid names happens before insert, so any row events irrelevant.
    eff=_effective_preread(opts,'TBLN',for_import)
    limit=_apply_limit_count(opts,'TBLN') if for_import else None
    # Determine included events count (row events only, zero rows count as rows for preread?) If limit, included row events count = limit.
    # Convert events to rows/errors classification
    rows=[]
    bulk_err=None
    preread_target=eff if eff and eff>0 else 0
    event_row_index=0
    for ev in row_events:
        if isinstance(ev,tuple) and ev and ev[0]=='ERR':
            if event_row_index < preread_target or (not rows and not first_data_seen):
                # If error occurs before any successful data and names not yet? Original raises pre error.
                raise ImportPreError(ev[1])
            if limit is not None and event_row_index>=limit:
                break
            bulk_err=ev[1]
            break
        # ev is a row list
        if limit is not None and event_row_index>=limit:
            break
        rows.append(ev)
        event_row_index+=1
    info.bulk_error=bulk_err
    if limit is not None:
        info.preread_rows=rows; info.remaining_rows=[]
    else:
        info.preread_rows=rows[:preread_target] if preread_target>0 else []
        # Filter zero rows in remaining to mirror bulk skipping (importer will also skip)
        info.remaining_rows=rows[preread_target:] if preread_target>0 else rows
    # If no data but names present, EOF debug already set; preread/remain empty.
    return info

def _text_reader(opts, data_text, for_import=True):
    info=ReaderInfo(); info.format_kind='TEXT'; info.format_display='Unknown'
    lines=split_go_lines(data_text)
    skip=getattr(opts,'is')
    idx=0
    if skip and skip>0:
        for i in range(skip):
            if idx<len(lines):
                debug_log(f"Skip row:{_go_slice_str([lines[idx]])}")
                idx+=1
            else:
                error_log("ERROR: skip error EOF")
                break
    work=lines[idx:]
    limit=_apply_limit_count(opts,'TEXT') if for_import else None
    if limit is not None:
        work=work[:limit]
    rows=[[l] for l in work]
    info.names=['text']; info.types=['text']
    # For import, TEXT inserts all as preread/bulk one group; for analyze samples handled separately (empty)
    info.preread_rows=rows; info.remaining_rows=[]
    return info

def _slice_by_visual(line, start_w, end_w):
    # include chars whose starting visual pos is in [start, end)
    pos=0; out=[]
    for ch in line:
        w=rune_width(ch)
        if start_w <= pos < end_w:
            out.append(ch)
        pos+=w
        if pos>= 10**18:break
    return ''.join(out)

def _visual_len(line):
    return sum(rune_width(ch) for ch in line)

def _tokens_visual(line):
    toks=[]; pos=0; i=0
    while i<len(line):
        while i<len(line) and line[i]==' ':
            i+=1; pos+=1
        if i>=len(line):break
        start_w=pos; start_i=i; chars=[]
        while i<len(line) and line[i]!=' ':
            ch=line[i]; chars.append(ch); pos+=rune_width(ch); i+=1
        toks.append((start_w,pos,''.join(chars)))
    return toks

def _width_reader(opts, data_text, for_import=True):
    info=ReaderInfo(); info.format_kind='WIDTH'; info.format_display='WIDTH'
    lines=split_go_lines(data_text)
    skip=getattr(opts,'is')
    idx=0
    if skip and skip>0:
        # Width skip discards lines (first lines before header). Debug Skip row format unknown; use Go slice of the eventual? We log raw line as one field approx.
        for i in range(skip):
            if idx<len(lines):
                debug_log(f"Skip row:{_go_slice_str([lines[idx]])}")
                idx+=1
            else:
                error_log("ERROR: skip error EOF"); break
    work=lines[idx:]
    if not work:
        info.names=[]; info.types=[]; return info
    header=work[0]
    data_lines=work[1:]
    header_tokens=_tokens_visual(header)
    if not header_tokens:
        info.names=[]; info.types=[]; return info
    # candidate starts per token
    starts=[0]
    # Data token starts sets
    data_starts=[]
    for dl in data_lines:
        data_starts.append([t[0] for t in _tokens_visual(dl)])
    chosen_starts=[0]
    for ti in range(1,len(header_tokens)):
        prev_end=header_tokens[ti-1][1]
        tok_start=header_tokens[ti][0]
        candidates=[]
        for starts_list in data_starts:
            for s in starts_list:
                if prev_end < s <= tok_start:
                    candidates.append(s)
        if candidates:
            chosen_starts.append(min(candidates))
    # Names by slicing header
    names=[]
    for i,st in enumerate(chosen_starts):
        en=chosen_starts[i+1] if i+1<len(chosen_starts) else _visual_len(header)+1000000
        nm=_slice_by_visual(header,st,en).strip(' \t')
        names.append(nm)
    info.names=names; info.types=['text']*len(names)
    # Rows
    if not data_lines:
        info.preread_rows=[[]]; info.remaining_rows=[]; return info
    rows=[]
    for dl in data_lines:
        if dl=="":
            # blank line in width Reader may produce zero row or empty fields. We'll produce [] in preread but importer remaining skips.
            rows.append([]); continue
        row=[]
        vlen=_visual_len(dl)
        for ci,st in enumerate(chosen_starts):
            en=chosen_starts[ci+1] if ci+1<len(chosen_starts) else vlen+1000000
            seg=_slice_by_visual(dl,st,en)
            # token overflow extension
            if ci+1<len(chosen_starts) and seg and not seg.endswith(' '):
                # char at visual pos en
                # find char starting at en
                pos=0; ext_chars=[]
                # Build chars from en onward
                for ch in dl:
                    w=rune_width(ch)
