def create_reader(opts, format_kind, data_bytes, jq_expr, for_import=True):
    data_text=None
    if format_kind!='JSON':
        data_text=data_bytes.decode('utf-8','surrogateescape') if isinstance(data_bytes,(bytes,bytearray)) else data_bytes
    if format_kind in ('CSV','TSV','PSV'):
