# ---------------- GoTime for sqlite date/boolean decltype conversions ----------------
class GoTime:
    def __init__(self,year,month,day,hour,minute,second,frac="",tz_offset_min=0):
        self.year=year;self.month=month;self.day=day;self.hour=hour;self.minute=minute;self.second=second
        self.frac=frac.rstrip('0') if frac else ""
        self.tz_offset_min=tz_offset_min
    def _tzstr(self):
        if self.tz_offset_min==0:return "Z"
        sign='+' if self.tz_offset_min>=0 else '-'; a=abs(self.tz_offset_min); return f"{sign}{a//60:02d}:{a%60:02d}"
    def rfc3339(self):
        return f"{self.year:04d}-{self.month:02d}-{self.day:02d}T{self.hour:02d}:{self.minute:02d}:{self.second:02d}{self._tzstr()}"
    def rfc3339nano(self):
        base=f"{self.year:04d}-{self.month:02d}-{self.day:02d}T{self.hour:02d}:{self.minute:02d}:{self.second:02d}"
        if self.frac:base+='.'+self.frac
