    # Howard Hinnant algorithm, z = days since 1970-01-01 -> convert to days since civil 0000? Use algorithm shifted to 719468
    z += 719468
    era = (z if z>=0 else z-146096)//146097
    doe = z - era*146097
    yoe = (doe - doe//1460 + doe//36524 - doe//146096)//365
