def tokenize_sql(query):
    tokens=[]
    i=0; n=len(query)
    cur=[]
    def flush():
        if cur:
            tokens.append(''.join(cur)); cur.clear()
    in_quote=None
    while i<n:
        ch=query[i]
        if in_quote is not None:
            cur.append(ch)
            if ch=='\\' and i+1<n:
                # backslash escapes next char for token scanning
                cur.append(query[i+1]); i+=2; continue
            if ch==in_quote:
                if i+1<n and query[i+1]==in_quote:
                    cur.append(query[i+1]); i+=2; continue
                in_quote=None; i+=1; continue
            i+=1; continue
        if ch in ('"',"'",'`'):
            in_quote=ch; cur.append(ch); i+=1; continue
        if ch in (' ','\t','\n','\r','(',')',',',';','='):
            flush(); tokens.append(ch); i+=1; continue
        cur.append(ch); i+=1
    flush()
    return tokens

