    for idx,tok in enumerate(tokens):
        upper=tok.upper()
        if upper in TRIGGER_KEYWORDS:
            expect=True; list_active=True; continue
        if upper in RESET_KEYWORDS:
            expect=False; list_active=False; continue
        if tok==',' :
            if list_active:
                expect=True
            continue
        if expect:
