                continue
            if tok==')':
                # Observed capturing an empty table name
                occ.append(TableOccurrence("", idx))
                expect=False; continue
            # A trigger keyword would have been handled above.
            occ.append(TableOccurrence(tok, idx))
            expect=False
            continue
    return occ

def quoted_name(name):
    if name=="":
        return ""
    if name[0]=='`':
        return name
    return '`'+name+'`'

def unquoted_name(name):
    if len(name)>=2 and ((name[0]=='`' and name[-1]=='`') or (name[0]=='"' and name[-1]=='"')):
        return name[1:-1]
    return name

