    # Given an identifier string generated by quoted_name, what is actual sqlite table name? If ident starts/ends with backticks, sqlite unescapes doubled backticks.
    if len(ident)>=2 and ident[0]=='`' and ident[-1]=='`':
        inner=ident[1:-1]
        return inner.replace('``','`')
    return ident

