def read_stdin_all():
    global _stdin_cache
    if _stdin_cache is None:
        try:
            _stdin_cache=sys.stdin.buffer.read()
        except Exception:
            _stdin_cache=b""
    return _stdin_cache

def open_table_data(occ):
    """Return (data_bytes or None if open failed skip, is_glob bool)"""
    file_part=occ.file_part
    # stdin check based on file_part exactly '-'
    if file_part=="-":
        data=read_stdin_all()
        try:
            data=maybe_decompress(data)
        except Exception as e:
            # Decompression errors are handled by wrapping data in a special exception at reader stage.
            # For simplicity raise ImportPreError with message details at import time (caller handles specially)
            raise ImportPreError(str(e) if str(e) else "unexpected EOF")
        return data, False
    pattern=unquoted_name(file_part)
    if has_glob_meta(pattern):
        try:
            matches=go_glob(pattern)
        except BadPattern:
            debug_log("syntax error in pattern")
            return None, True
        if not matches:
            debug_log(f"open {pattern}: no such file or directory")
            return None, True
        parts=[]
        for path in matches:
            debug_log(f"Open: [{path}]")
            if os.path.isdir(path):
                raw=b""
            else:
                try:
                    with open(path,'rb') as f:raw=f.read()
                except OSError as e:
                    debug_log(f"open {path}: {_os_error_str(e)}")
                    return None, True
            try:
                raw=maybe_decompress(raw)
            except Exception as e:
                raise ImportPreError(str(e) if str(e) else "unexpected EOF")
            parts.append(raw+b'\n')
            debug_log(f"Close: [{path}]")
        return b''.join(parts), True
    else:
        path=pattern
        if os.path.isdir(path):
            return b"", False
        try:
            with open(path,'rb') as f:raw=f.read()
        except OSError as e:
            debug_log(f"open {pattern}: {_os_error_str(e)}")
            return None, False
        try:
            raw=maybe_decompress(raw)
        except EOFError:
            # Original sometimes treats gzip truncated differently; propagate as import pre error "unexpected EOF" (bulk stage)
            raise ImportPreError("unexpected EOF")
        except Exception as e:
            raise ImportPreError(str(e))
        return raw, False

