# ---------------- writers ----------------
class WriterCtx:
    def __init__(self, opts, out_format, stream):
        self.opts=opts
        self.format=out_format
        self.stream=stream  # binary stream
        self.yaml_doc_count=0
        # delimiters precomputed
        if out_format=='CSV':
            try:
                self.csv_delim=get_separator(opts.od)
            except Exception:
                self.csv_delim=','
            self.quote_char=opts.oq[0] if opts.oq else '\x00'
        elif out_format=='RAW':
            try:
                self.raw_delim=go_unquote_double_content(opts.od)
            except Exception:
                self.raw_delim=""
    def write_bytes(self,b):
        self.stream.write(b)
    def write_text(self,s):
        self.stream.write(s.encode('utf-8','surrogateescape'))

def select_output_format(opts):
    # precedence high->low observed
    if opts.oltsv:return 'LTSV'
    if opts.ojson:return 'JSON'
    if opts.oraw:return 'RAW'
    if opts.omd:return 'MD'
    if opts.oat:return 'AT'
    if opts.ovf:return 'VF'
    if opts.otbln:return 'TBLN'
    if opts.ojsonl:return 'JSONL'
    if opts.oyaml:return 'YAML'
    if opts.ocsv:return 'CSV'
    return 'CSV'

def any_output_format(opts):
    return any([opts.oltsv,opts.ojson,opts.oraw,opts.omd,opts.oat,opts.ovf,opts.otbln,opts.ojsonl,opts.oyaml,opts.ocsv])

OUTPUT_GUESS_MAP={'csv':'CSV','ltsv':'LTSV','json':'JSON','jsonl':'JSONL','yaml':'YAML','yml':'YAML','tbln':'TBLN','md':'MD','at':'AT','vf':'VF','raw':'RAW'}
def guess_output_format(filename):
    cur=filename
    while True:
        ext=_filepath_ext(cur)
        if ext=="":return 'CSV'
        key=ext[1:].lower()
        if key in OUTPUT_GUESS_MAP:return OUTPUT_GUESS_MAP[key]
        cur=cur[:-len(ext)]

def compression_from_filename(filename):
    ext=_filepath_ext(filename)
    if not ext:return ""
    key=ext[1:].lower()
    if key in ('gz','bz2','xz','zst','lz4'):return key
    return ""

def compression_from_oz(oz):
    k=(oz or "").lower()
    if k in ('gz','gzip'):return 'gz'
    if k in ('bz2','bzip2'):return 'bz2'
    if k in ('xz',):return 'xz'
    if k in ('zstd','zst'):return 'zstd'
    if k in ('lz4',):return 'lz4'
    return ""

def _csv_line(ctx, fields):
    """fields are list of (text, is_null_original)"""
    opts=ctx.opts
    delim=ctx.csv_delim
    quote=ctx.quote_char
    out_parts=[]
    for text,is_null in fields:
        if is_null:
            out_parts.append(text)  # already onull substituted, unquoted
            continue
        needs=False
        if opts.oaq:
            needs=True
        else:
            if text==r'\.':
                needs=True
            elif delim and delim in text:
                needs=True
            elif quote and quote in text:
                needs=True
            elif '\n' in text or '\r' in text:
                needs=True
            elif text and _is_unicode_space(text[0]):
                needs=True
        if needs:
            escaped=text.replace(quote, quote+quote) if quote else text
            out_parts.append(quote+escaped+quote)
        else:
            out_parts.append(text)
    line=delim.join(out_parts)
    line += '\r\n' if opts.ocrlf else '\n'
    ctx.write_text(line)

