    opts=ctx.opts
    delim=ctx.raw_delim
    if opts.oh:
        ctx.write_text(delim.join(columns)+'\n')
    for row in rows:
        fields=[_value_text_pair(ctx,v)[0] for v in row]
        ctx.write_text(delim.join(fields)+'\n')

