    if isinstance(v,(bytes,bytearray)):
        s=go_value_string(bytes(v))
        return _json_convert_str(s)
    if isinstance(v,str):
        return _json_convert_str(v)
    return v

def _json_convert_str(s):
    if s and s[0] in '[{':
        try:
            p=JSONParser(s.encode('utf-8','surrogateescape'))
            parsed=p.parse_value()
            p.skip_ws()
            if p.eof():
                return RawJSON(s)
        except Exception:
            return s
    return s

