# YAML emitter
_YAML_BOOL_WORDS={'y','yes','n','no','true','false','on','off'}
def _yaml_is_plain_safe(s, is_key=False):
    if s=="":return False
    if s!=s.strip(' \t\r\n'):return False
    low=s.lower()
    if low in _YAML_BOOL_WORDS:return False
    if low in ('null','~','true','false','.inf','-.inf','+.inf','.nan'):return False
    # numeric-looking (including 1e3 for emitter safety)
    if re.fullmatch(r'[+-]?[0-9][0-9_]*',s):return False
    if re.fullmatch(r'[+-]?(\.[0-9]+|[0-9]+(\.[0-9]*)?)([eE][+-]?[0-9]+)?',s) and any(c.isdigit() for c in s):return False
    if re.fullmatch(r'0x[0-9a-fA-F_]+|0o[0-7_]+|0b[01_]+',s):return False
    if re.fullmatch(r'[0-9]{4}-[0-9]{2}-[0-9]{2}.*',s):return False
    if s[0] in '-?:,[]{}#&*!|>\'"%@`':return False
    if s.startswith('---') or s.startswith('...'):return False
    if ': ' in s or s.endswith(':'):return False
    if ' #' in s or s.startswith('#'):return False
    if any(ord(ch)<0x20 for ch in s):return False
    if '\\' in s:return False
    if '"' in s:
        # plain scalars can contain " in middle in block context; observed plain output for a"b. Keep plain unless starts with it (handled)
        pass
    return True

def _yaml_double_quote(s):
    out=['"']
    for ch in s:
        if ch=='"':out.append('\\"')
        elif ch=='\\':out.append('\\\\')
        elif ch=='\n':out.append('\\n')
        elif ch=='\r':out.append('\\r')
        elif ch=='\t':out.append('\\t')
        elif ord(ch)<0x20 or ord(ch)==0x7f:out.append(f'\\x{ord(ch):02X}')
        elif 0xD800 <= ord(ch) <= 0xDFFF:out.append('\\ufffd')
        else:out.append(ch)
    out.append('"')
    return ''.join(out)

def _yaml_format_string(s,is_key=False):
    if _yaml_is_plain_safe(s,is_key):
        return s
    return _yaml_double_quote(s)

def _yaml_format_float(v):
    if math.isnan(v):return '.nan'
    if math.isinf(v):return '.inf' if v>0 else '-.inf'
    s=go_float_g(v)
    if '.' not in s and 'e' not in s and 'E' not in s:
        s += '.0'
    return s

def _yaml_scalar_str(v,is_key=False):
    if v is None:return 'null'
    if isinstance(v,bool):return 'true' if v else 'false'
    if isinstance(v,JsonNumber):
        # When a JsonNumber arises from YAML parsing our resolver returns int/float, not JsonNumber. From JSON nested structures in YAML conversion, numbers parsed by YAML parser produce int/float. This branch for keys etc.
        return str(v)
    if isinstance(v,int):return str(v)
    if isinstance(v,float):return _yaml_format_float(v)
    if isinstance(v,GoTime):return v.rfc3339nano()
    if isinstance(v,str):return _yaml_format_string(v,is_key)
    return _yaml_format_string(str(v),is_key)

def _yaml_key_str(k):
    if isinstance(k,str) and not isinstance(k,JsonNumber):return _yaml_format_string(k,True)
    if isinstance(k,bool):return _yaml_format_string('true' if k else 'false',True)
    if k is None:return _yaml_format_string('null',True)
    return _yaml_scalar_str(k,True)

def _yaml_render(value, indent):
    """Return list of lines for a block node at indent column (for mappings/sequences). Scalars handled by caller."""
    lines=[]
    if isinstance(value, dict):
        if not value:
            lines.append(' '*indent+'{}'); return lines
        for k, v in value.items():
            lines.extend(_yaml_render_kv(k,v,indent))
        return lines
    if isinstance(value, list):
        # value as list of pairs? Top-level rows is a list of dict-like pair lists; caller converts rows to list of ('__pairs__', [...])? Instead this generic expects Python list.
        if not value:
            lines.append(' '*indent+'[]'); return lines
        for item in value:
            lines.extend(_yaml_render_seq_item(item,indent))
        return lines
    lines.append(' '*indent+_yaml_scalar_str(value))
    return lines

def _yaml_render_pairs(pairs, indent):
    lines=[]
    for k,v in pairs:
        lines.extend(_yaml_render_kv(k,v,indent))
    return lines

def _yaml_render_kv(k,v,indent):
    key=_yaml_key_str(k)
    prefix=' '*indent+key+':'
    if isinstance(v,dict):
        if not v:return [prefix+' {}']
        return [prefix]+_yaml_render(v,indent+2)
    if isinstance(v,list):
        if not v:return [prefix+' []']
        return [prefix]+_yaml_render(v,indent)
    if isinstance(v, tuple) and len(v)==2 and v[0]=='__pairs__':
        # not used
        return [prefix]+_yaml_render_pairs(v[1],indent+2)
    return [prefix+' '+_yaml_scalar_str(v)]

def _yaml_render_seq_item(item, indent):
    dash_prefix=' '*indent+'- '
    if isinstance(item,dict):
        if not item:return [dash_prefix+'{}']
        sub_lines=_yaml_render(item,indent+2)
        if sub_lines:
            # Replace leading spaces of first line with dash prefix
            first=sub_lines[0]
            sub_lines[0]=dash_prefix+first[indent+2:]
        return sub_lines
    if isinstance(item, tuple) and len(item)==2 and item[0]=='__pairs__':
        sub_lines=_yaml_render_pairs(item[1],indent+2)
        if sub_lines:
            sub_lines[0]=dash_prefix+sub_lines[0][indent+2:]
            return sub_lines
        return [dash_prefix+'{}']
    if isinstance(item,list):
        if not item:return [dash_prefix+'[]']
        sub_lines=_yaml_render(item,indent+2)
        if sub_lines:
            sub_lines[0]=dash_prefix+sub_lines[0][indent+2:]
        return sub_lines
    return [dash_prefix+_yaml_scalar_str(item)]

def _yaml_convert(ctx,v):
    opts=ctx.opts
    if isinstance(v,GoTime):
        # Leave as GoTime for scalar formatting; if onull set and non-string time, gojq-esque bug unknown.
        return v
    if v is None:
        return opts.onull if opts.onull_set else None
    if isinstance(v,bool):
        return opts.onull if opts.onull_set else v
    if isinstance(v,(int,float)):
        return opts.onull if opts.onull_set else v
    if isinstance(v,(bytes,bytearray)):
        s=bytes(v).decode('utf-8','replace')
        return _yaml_convert_str(s)
    if isinstance(v,str):
        return _yaml_convert_str(v)
    return v

def _yaml_convert_str(s):
    if s=="":
        return None
    try:
        docs=parse_yaml_documents(s)
        if not docs:
            return None
        return docs[0]
    except Exception:
        return s

def write_yaml_result(ctx, columns, rows):
    if ctx.yaml_doc_count>0:
        ctx.write_text('---\n')
    ctx.yaml_doc_count+=1
    if not rows:
        ctx.write_text('[]\n'); return
    # build a list where each row is ('__pairs__', pairs)
    top=[]
    for row in rows:
        pairs=[]
        for name,v in zip(columns,row):
            pairs.append((name,_yaml_convert(ctx,v)))
        top.append(('__pairs__',pairs))
    # Render top as sequence at indent0
    lines=[]
    for item in top:
        lines.extend(_yaml_render_seq_item(item,0))
    ctx.write_text('\n'.join(lines)+'\n')

# AT/MD table writer
_NUM_RE=re.compile(r'^-?([0-9]+|[0-9]{1,3}(,[0-9]{3})+)(\.[0-9]+)?$')
def _is_numeric_str(s):
    return bool(_NUM_RE.match(s.strip(' \t')))

def _word_wrap_line(line, limit=30):
    if display_width(line)<=limit:
        return [line]
    # Greedy by spaces (preserve words). Split on single spaces keeping semantics approximate.
    words=line.split(' ')
    lines=[]; cur=""
    for w in words:
        if cur=="":
            cur=w
        elif display_width(cur)+1+display_width(w)<=limit:
            cur=cur+' '+w
        else:
            lines.append(cur); cur=w
    if cur!="" or not lines:
        lines.append(cur)
    return lines

def _cell_segments(text, nowrap):
    segs=[]
    for part in text.split('\n'):
        if nowrap:
            segs.append(part)
        else:
            segs.extend(_word_wrap_line(part,30))
    return segs if segs else ['']

def write_table_result(ctx, columns, rows, markdown=False):
    opts=ctx.opts
    # Prepare string rows and header
    header_texts=list(columns)
    data_texts=[]
    for row in rows:
        data_texts.append([_value_text_pair(ctx,v)[0] for v in row])
    # MD escaping only data cells (pipe->\|) BEFORE segmentation/width
    if markdown:
        data_texts=[[t.replace('|','\\|') for t in r] for r in data_texts]
    # segments
    header_segs=[_cell_segments(t,opts.onowrap) for t in header_texts]
    data_segs=[[_cell_segments(t,opts.onowrap) for t in r] for r in data_texts]
    # widths
    ncol=len(columns)
    if ncol==0:
        # tablewriter with no columns for analyze etc: output plus lines handled by analyze custom; for query no.
        return
    widths=[0]*ncol
    for i in range(ncol):
        widths[i]=max([display_width(s) for s in header_segs[i]]+[0])
    for r in data_segs:
        for i in range(ncol):
            widths[i]=max(widths[i], max([display_width(s) for s in r[i]]+[0]))
    def border_line():
        return '+' + ''.join('-'*(widths[i]+2)+'+' for i in range(ncol)) + '\n'
    def format_row(segs_for_row, aligns):
        height=max(len(segs) for segs in segs_for_row) if segs_for_row else 1
        out_lines=[]
        for li in range(height):
            parts=[]
            for i in range(ncol):
                seg=segs_for_row[i][li] if li<len(segs_for_row[i]) else ''
                w=widths[i]
                if aligns[i]=='center':
                    # pad with floor left
                    sw=display_width(seg); pad=w-sw; left=pad//2; right=pad-left
                    cell=' '*(left)+seg+' '*(right)
                elif aligns[i]=='right':
                    cell=pad_display(seg,w,'right')
                else:
                    cell=pad_display(seg,w,'left')
                parts.append(' '+cell+' ')
            out_lines.append('|' + '|'.join(parts) + '|\n')
        return ''.join(out_lines)
    # header aligns center
    if not markdown:
        ctx.write_text(border_line())
        ctx.write_text(format_row(header_segs,['center']*ncol))
        ctx.write_text(border_line())
        for idx, r in enumerate(data_segs):
            aligns=[]
            for i, orig_text in enumerate(data_texts[idx]):
                # alignment determined by each segment? Use original cell trimmed whole: if cell contains newline, tablewriter might inspect per line. We'll determine per cell based on? For multi-line cells, use segment-specific in format; simpler recompute here with original for all lines. If original has newline, not numeric.
                aligns.append('right' if _is_numeric_str(orig_text) else 'left')
            # To handle per-segment numeric for multiline, adjust by producing each line manually if any segment cell has >1 line - our format_row picks align per column not per segment. Approximate: if a data cell's first line segment is numeric, the row alignment was right anyway in tests.
            ctx.write_text(format_row(r,aligns))
        ctx.write_text(border_line())
    else:
        ctx.write_text(format_row(header_segs,['center']*ncol))
        ctx.write_text('|' + ''.join('-'*(widths[i]+2)+'|' for i in range(ncol)) + '\n')
        for idx,r in enumerate(data_segs):
            aligns=['right' if _is_numeric_str(t) else 'left' for t in data_texts[idx]]
            ctx.write_text(format_row(r,aligns))

def write_result(ctx, columns, rows):
    fmt=ctx.format
    if fmt=='CSV':
        write_csv_result(ctx,columns,rows)
    elif fmt=='RAW':
