def _csv_line(ctx, fields):
    """fields are list of (text, is_null_original)"""
    opts=ctx.opts
    delim=ctx.csv_delim
    quote=ctx.quote_char
    out_parts=[]
    for text,is_null in fields:
        if is_null:
            out_parts.append(text)  # already onull substituted, unquoted
            continue
        needs=False
        if opts.oaq:
            needs=True
        else:
            if text==r'\.':
                needs=True
            elif delim and delim in text:
                needs=True
            elif quote and quote in text:
                needs=True
            elif '\n' in text or '\r' in text:
                needs=True
            elif text and _is_unicode_space(text[0]):
                needs=True
        if needs:
            escaped=text.replace(quote, quote+quote) if quote else text
            out_parts.append(quote+escaped+quote)
        else:
            out_parts.append(text)
    line=delim.join(out_parts)
