    if re.fullmatch(r'[+-]?[0-9][0-9_]*',s):return False
    if re.fullmatch(r'[+-]?(\.[0-9]+|[0-9]+(\.[0-9]*)?)([eE][+-]?[0-9]+)?',s) and any(c.isdigit() for c in s):return False
    if re.fullmatch(r'0x[0-9a-fA-F_]+|0o[0-7_]+|0b[01_]+',s):return False
    if re.fullmatch(r'[0-9]{4}-[0-9]{2}-[0-9]{2}.*',s):return False
    if s[0] in '-?:,[]{}#&*!|>\'"%@`':return False
    if s.startswith('---') or s.startswith('...'):return False
    if ': ' in s or s.endswith(':'):return False
    if ' #' in s or s.startswith('#'):return False
    if any(ord(ch)<0x20 for ch in s):return False
    if '\\' in s:return False
    if '"' in s:
        # plain scalars can contain " in middle in block context; observed plain output for a"b. Keep plain unless starts with it (handled)
        pass
    return True

