        # attempt dial
        _dial_tcp_or_unix_mysql(addr)
        # If connection succeeded we cannot speak MySQL; treat as begin error generic
        fatal("begin: mysql connection not supported")
    debug_log(f"driver: {driver}, dsn: {dsn}")
    if driver=='postgres':
        addr, err = _postgres_parse_dsn(dsn)
        if err:
            fatal(f"begin: {err}")
        _dial_tcp_postgres(addr)
        fatal("begin: postgres connection not supported")
    # sqlite
    target,is_uri=_sqlite_target(dsn)
    conn=None
