    _register_sqlite_functions(t, ext=ext)

def _mysql_parse_dsn(dsn):
    # Returns (addr_str, error_str)
    # Go mysql driver DSN format: [username[:password]@][protocol[(address)]]/dbname[?param=...]
    if '/' not in dsn:
        return None, "invalid DSN: missing the slash separating the database name"
    # Find slash separating db name: driver finds last '/'? It parses by locating '/' after @ stuff. Simplify: find first '/' that is not inside parentheses?
    # Check network address parentheses
    # Locate '@' then protocol segment
    before_slash=dsn.rsplit('/',1)[0] if False else None
    # MySQL driver algorithm: look for last '/' as db separator? Use dsn.find for '/' from a position after possible '('.
    # We'll approximate common cases:
    # Search for '(' in the segment before first '/'
    head=dsn.split('/',1)[0]
    if '(' in head and ')' not in head:
        return None, "invalid DSN: network address not terminated (missing closing brace)"
    proto='tcp'; addr='127.0.0.1:3306'
    # Remove user info up to last '@'
    if '@' in head:
        proto_addr=head.rsplit('@',1)[-1]
    else:
        proto_addr=head
    if proto_addr:
        if '(' in proto_addr:
            pp=proto_addr[:proto_addr.find('(')]
            if pp:proto=pp
            inside=proto_addr[proto_addr.find('(')+1:proto_addr.rfind(')')] if ')' in proto_addr else ''
            if inside:addr=inside
        elif proto_addr:
            proto=proto_addr
    if proto=='tcp' and addr and ':' not in addr:
        addr=addr+':3306'
    if proto=='unix' and not addr:
        addr='/tmp/mysql.sock'
    return (proto,addr), None

def _dial_tcp_or_unix_mysql(addr_tuple):
    proto,addr=addr_tuple
    import socket
    if proto=='unix':
        # Go error: dial unix <path>: connect: no such file or directory / connection refused
        try:
            s=socket.socket(socket.AF_UNIX,socket.SOCK_STREAM); s.settimeout(2); s.connect(addr); s.close(); return
        except FileNotFoundError:
            fatal(f"begin: dial unix {addr}: connect: no such file or directory")
        except ConnectionRefusedError:
            fatal(f"begin: dial unix {addr}: connect: connection refused")
        except OSError as e:
            fatal(f"begin: dial unix {addr}: connect: {_os_error_str(e)}")
    # tcp
    host,port=_split_hostport(addr,'3306')
    _dial_tcp(host,port)

def _split_hostport(addr, default_port):
    addr=str(addr)
    if addr.startswith('['):
        end=addr.find(']')
        if end>=0:
            host=addr[1:end]; rest=addr[end+1:]
            if rest.startswith(':'):return host, rest[1:]
            return host, default_port
    if ':' in addr:
        h,p=addr.rsplit(':',1); return h,p
    return addr, default_port

def _dial_display(host,port):
    if host=='localhost':
        return f"[::1]:{port}"
    if ':' in host and not host.startswith('['):
        return f"[{host}]:{port}"
    return f"{host}:{port}"

def _dial_tcp(host,port):
    import socket
    if host=='':host='127.0.0.1'
    try:
        # Use getaddrinfo + create_connection behavior; display as Go would
        s=socket.create_connection((host,int(port)),timeout=2); s.close(); return
    except ConnectionRefusedError:
        fatal(f"begin: dial tcp {_dial_display(host,port)}: connect: connection refused")
    except socket.gaierror as e:
        fatal(f"begin: dial tcp: lookup {host}: {e.strerror or 'no such host'}")
    except (TimeoutError,socket.timeout):
        fatal(f"begin: dial tcp {_dial_display(host,port)}: i/o timeout")
    except OSError as e:
        fatal(f"begin: dial tcp {_dial_display(host,port)}: connect: {_os_error_str(e)}")
    return

def _postgres_parse_dsn(dsn):
    # Returns ((host,port), error)
    host=os.environ.get('PGHOST','localhost'); port=os.environ.get('PGPORT','5432')
    if dsn.startswith('postgres://') or dsn.startswith('postgresql://'):
        p=urlparse(dsn)
        if p.hostname:host=p.hostname
        if p.port:port=str(p.port)
        return (host,port), None
    # keyword string
    if dsn.strip()!="":
        # Tokenize key=value pairs, value can be quoted.
        i=0; n=len(dsn)
        while i<n:
            while i<n and dsn[i]==' ':i+=1
            if i>=n:break
            start=i
            while i<n and dsn[i] not in ('=',' '):i+=1
            key=dsn[start:i]
            if i>=n or dsn[i]!='=':
                return None, f'missing "=" after "{key}" in connection info string"'
            i+=1
            # value
            if i<n and dsn[i]=="'":
                i+=1; val=""
                while i<n and dsn[i]!="'":
                    if dsn[i]=='\\' and i+1<n:i+=1
                    val+=dsn[i]; i+=1
                i+=1 if i<n else 0
            else:
                start=i
                while i<n and dsn[i]!=' ':i+=1
                val=dsn[start:i]
            if key=='host':host=val
            elif key=='port':port=val
    return (host,port), None

def _dial_tcp_postgres(addr_tuple):
    host,port=addr_tuple
    _dial_tcp(host,port)

