def _sqlite_target(dsn):
    if dsn=="":
        return (":memory:",False)
    if dsn==":memory:":
        return (":memory:",False)
    if dsn.startswith("file:"):
        return (dsn,True)
    if '?' in dsn:
        path,qs=dsn.split('?',1)
        # Keep only sqlite URI params (mode,cache,vfs,immutable,memory etc)
        kept=[]
        for part in qs.split('&'):
            if not part:continue
            if '=' in part:
                k,v=part.split('=',1)
                if k.startswith('_'):continue
                kept.append(part)
            else:
                if not part.startswith('_'):kept.append(part)
        uri="file:"+path
        if kept:uri+='?'+'&'.join(kept)
        return (uri,True)
    return (dsn,False)

def _begin_error_message(e, dsn):
    msg=str(e)
    if msg=="unable to open database file":
        # Determine likely cause from target
        target,is_uri=_sqlite_target(dsn)
        path=target
        mode=None
        if is_uri and target.startswith('file:'):
            # parse pathname from URI
            rest=target[5:]
            path=rest.split('?',1)[0]
            if 'mode=' in target:
                try:mode=parse_qs(target.split('?',1)[1]).get('mode',[None])[0]
                except Exception:mode=None
            path=url_unquote(path)
        if path in (':memory:',''):
            return msg
        if os.path.isdir(path):
            return "unable to open database file: is a directory"
        parent=os.path.dirname(path)
        if parent and not os.path.isdir(parent):
            return "unable to open database file: no such file or directory"
        if mode in ('ro','rw') and not os.path.exists(path):
            return "unable to open database file: no such file or directory"
        if parent and not os.access(parent, os.W_OK):
            return "unable to open database file: permission denied"
        if os.path.exists(path) and not os.access(path, os.R_OK|os.W_OK) and mode!='ro':
            # still could be readonly file system; sqlite gives "attempt to write a readonly database" later not open
            return "unable to open database file: no such file or directory"
        return "unable to open database file: no such file or directory"
    return msg

def connect_db(driver, dsn):
    if driver=="":
        driver="sqlite3"
    known={'sqlite3','sqlite3_ext','postgres','mysql'}
    if driver not in known:
        fatal(f"connect: sql: unknown driver {go_quote(driver)} (forgotten import?)")
    if driver=='mysql':
        addr, err = _mysql_parse_dsn(dsn)
        if err:
            fatal(f"connect: {err}")
        debug_log(f"driver: {driver}, dsn: {dsn}")
        # attempt dial
        _dial_tcp_or_unix_mysql(addr)
        # If connection succeeded we cannot speak MySQL; treat as begin error generic
        fatal("begin: mysql connection not supported")
    debug_log(f"driver: {driver}, dsn: {dsn}")
    if driver=='postgres':
        addr, err = _postgres_parse_dsn(dsn)
        if err:
            fatal(f"begin: {err}")
        _dial_tcp_postgres(addr)
        fatal("begin: postgres connection not supported")
    # sqlite
    target,is_uri=_sqlite_target(dsn)
    conn=None
    try:
