def _sqlite_target(dsn):
    if dsn=="":
        return (":memory:",False)
    if dsn==":memory:":
        return (":memory:",False)
    if dsn.startswith("file:"):
        return (dsn,True)
    if '?' in dsn:
        path,qs=dsn.split('?',1)
        # Keep only sqlite URI params (mode,cache,vfs,immutable,memory etc)
        kept=[]
        for part in qs.split('&'):
            if not part:continue
            if '=' in part:
                k,v=part.split('=',1)
                if k.startswith('_'):continue
                kept.append(part)
            else:
                if not part.startswith('_'):kept.append(part)
        uri="file:"+path
        if kept:uri+='?'+'&'.join(kept)
        return (uri,True)
    return (dsn,False)

