        if os.path.isdir(path):
            return "unable to open database file: is a directory"
        parent=os.path.dirname(path)
        if parent and not os.path.isdir(parent):
            return "unable to open database file: no such file or directory"
        if mode in ('ro','rw') and not os.path.exists(path):
            return "unable to open database file: no such file or directory"
        if parent and not os.access(parent, os.W_OK):
            return "unable to open database file: permission denied"
        if os.path.exists(path) and not os.access(path, os.R_OK|os.W_OK) and mode!='ro':
