def execute_statements(db, opts, query, writer_ctx):
    preprocessed=preprocess_query(query)
    tokens=tokenize_sql(preprocessed)
    # Remove trailing separator tokens ';' plus space tokens after core? Preprocess string while suffix already handled semicolons adjacent ends. If tokens end with semicolon due spaces between semicolons, keep original debug behavior as much as possible.
    if tokens:
        debug_log(''.join(f'[{t}]' for t in tokens))
    all_occs=extract_table_occurrences(tokens)
    if not all_occs:
        debug_log("table not found")
    distinct=[]
    seen={}
    jq_counter=0
    for occ in all_occs:
        raw=occ.raw
        if raw in seen:
            continue
        # effective jq
        if occ.has_jq_suffix:
            occ.effective_jq=occ.jq_suffix
        else:
            occ.effective_jq=opts.ijq
        if occ.effective_jq:
            jq_counter+=1
            occ.table_base=f"{occ.file_part}::jq{jq_counter}"
        else:
            if occ.has_jq_suffix:
                occ.table_base=occ.file_part
            else:
                occ.table_base=occ.raw
        occ.sql_ident=quoted_name(occ.table_base)
        seen[raw]=occ
        distinct.append(occ)
    for occ in distinct:
        import_table(db,occ,opts)
    # rewrite
    rewritten=list(tokens)
    for occ in all_occs:
        d=seen.get(occ.raw)
        if d is not None and d.imported:
            rewritten[occ.token_idx]=d.sql_ident
    # split statements
    groups=[]; cur=[]
    for tok in rewritten:
        if tok==';':
            groups.append(cur); cur=[]
        else:
            cur.append(tok)
    groups.append(cur)
    for gidx,group in enumerate(groups):
        stmt=trim_space_go(''.join(group))
        if stmt=="":
            if gidx==len(groups)-1 and gidx>0:
                continue
            # Special case: a single ';' statement made of only semicolon tokens/spaces - original executes ';' successfully in some patterns; if the whole query tokens are only semicolons/spaces and there was content, treat as one exec ';'
            if all(t in (';',' ','\t','\n','\r') for t in tokens) and tokens:
                stmt=';'
            else:
                fatal_export("no SQL statement")
        debug_log(stmt)
        is_select=stmt.upper().startswith('SELECT')
        if is_select:
            cur=db.conn.cursor()
            try:
                cur.execute(stmt)
            except Exception as e:
                fatal_export(f"{_map_sqlite_error(e)} [{stmt}]")
            if cur.description is None:
                continue
            columns=[d[0] for d in cur.description]
            try:
                rows=cur.fetchall()
            except Exception as e:
                fatal_export(f"{_map_sqlite_error(e)} [{stmt}]")
            decls=infer_decltypes(db,stmt,columns)
            new_rows=[]
            for r in rows:
                nr=[]
                for i,v in enumerate(r):
                    if i < len(decls) and decls[i]:
                        nr.append(convert_decltype_value(v,decls[i]))
                    else:
                        nr.append(v)
                new_rows.append(tuple(nr))
            write_result(writer_ctx,columns,new_rows)
        else:
            cur=db.conn.cursor()
            try:
                cur.execute(stmt)
            except Exception as e:
                fatal_export(f"{_map_sqlite_error(e)} [{stmt}]")
    return

