def analyze_quote_name(name):
    if name.startswith('`'):
        return name
    # Plain if all chars are lowercase letters/digits/underscore and not reserved.
    if re.fullmatch(r'[a-z0-9_]+', name) and name not in _ANALYZE_RESERVED:
